/* ===================================================================
   Matebase · glosario.js
   EL VOCABULARIO. Cada entrada: {t: termino, d: definicion, v: variantes
   para la busqueda (opcional), i: tema donde se explica (opcional)}.

   Criterios al escribir una definicion:
     - Frase entera, no telegrama. El alumno llega aqui perdido.
     - Primero que ES, despues para que sirve o donde aparece.
     - Si una palabra significa cosas distintas en sitios distintos,
       una entrada por acepcion, diciendolo.
   =================================================================== */
window.GLOSARIO = [

/* ---------------- lógica y conjuntos ---------------- */
{ t: 'Proposición', d: 'Una frase de la que se puede decir, sin discusión, si es verdadera o falsa. «Siete es primo» lo es; «qué hora es» no, y «esta película es buena» tampoco, porque no hay manera de decidirlo. Toda la lógica se construye encima de esta idea.', i: 'lg-proposiciones' },
{ t: 'Conectiva', d: 'Cada una de las palabras con las que se enganchan proposiciones para formar otras más largas: <strong>y</strong>, <strong>o</strong>, <strong>no</strong>, <strong>si… entonces</strong>. Se llaman así porque conectan. Lo importante es que el valor de verdad del resultado queda determinado por el de las piezas, y eso es lo que permite calcular con frases.', v: 'conectiva lógica conector', i: 'lg-proposiciones' },
{ t: 'Tabla de verdad', d: 'La tabla que recoge todos los casos posibles de verdadero y falso para las proposiciones simples, y qué sale en cada uno. Con dos proposiciones hay cuatro filas; con tres, ocho. Es, literalmente, el plano de un circuito digital.', i: 'lg-proposiciones' },
{ t: 'Implicación', d: 'La conectiva «si A, entonces B». Solo es falsa en un caso: cuando A es verdadera y B falsa. Cuidado, porque no significa que A cause B, y no se puede dar la vuelta: que llover implique mojarse no significa que mojarse implique llover.', v: 'implicacion condicional si entonces', i: 'lg-proposiciones' },
{ t: 'Recíproca', d: 'Dada la implicación «si A entonces B», su recíproca es «si B entonces A». <strong>No son equivalentes</strong>, y confundirlas es el error clásico: que una prueba médica dé positivo en los enfermos no significa que todo positivo esté enfermo.', v: 'reciproca reciproco', i: 'lg-proposiciones' },
{ t: 'Contrarrecíproca', d: 'Dada «si A entonces B», su contrarrecíproca es «si no B, entonces no A». Esta sí es siempre equivalente a la original, y por eso demostrarla vale como demostración. A menudo es mucho más fácil de probar que la de partida.', v: 'contrarreciproca contrapositiva', i: 'lg-proposiciones' },
{ t: 'Cuantificador', d: 'La palabra que dice a cuántos elementos se aplica una propiedad. Hay dos: el universal <strong>∀</strong>, «para todo», y el existencial <strong>∃</strong>, «existe algún». Para tumbar un «para todo» basta un contraejemplo; para tumbar un «existe» hay que descartarlos todos.', i: 'lg-proposiciones' },
{ t: 'Contraejemplo', d: 'Un caso concreto que incumple una afirmación general y, por tanto, la destruye. Un solo contraejemplo basta: si alguien dice que todos los primos son impares, el 2 zanja la discusión.', i: 'lg-demostracion' },
{ t: 'Inducción', d: 'Método para demostrar que algo se cumple para todos los números naturales, sin comprobarlos uno a uno. Se demuestra el primer caso y se demuestra que, si vale para uno cualquiera, vale para el siguiente. Es el efecto dominó: tira la primera ficha y garantiza que cada una tira a la siguiente.', v: 'induccion principio de induccion', i: 'lg-demostracion' },
{ t: 'Reducción al absurdo', d: 'Demostrar algo suponiendo lo contrario y llegando a una contradicción. Si suponer que no se cumple lleva a un imposible, es que se cumple. Es como se depura una avería: «supongamos que el fallo está aquí»; si de ahí se sigue algo que no cuadra, no está ahí.', v: 'reduccion al absurdo absurdo contradiccion', i: 'lg-demostracion' },
{ t: 'Conjunto', d: 'Una colección de objetos bien determinada: dado cualquier objeto, tiene que estar claro si pertenece o no. No se pide nada más, ni orden, ni cantidad, ni que se parezcan entre sí. Con esta idea tan pobre se construye toda la matemática.', i: 'lg-conjuntos' },
{ t: 'Por extensión y por comprensión', d: 'Las dos maneras de dar un conjunto. <strong>Por extensión</strong> es enumerar sus elementos, {1, 2, 3, 4}. <strong>Por comprensión</strong> es dar la regla que cumplen, sin listarlos: «los naturales menores que 5 distintos de cero». La segunda es la única viable cuando hay infinitos.', v: 'extension comprension' , i: 'lg-conjuntos' },
{ t: 'Pertenencia (∈)', d: 'La relación entre un <em>elemento</em> y un conjunto: se lee «pertenece a». No confundir con la inclusión ⊂, que relaciona dos <em>conjuntos</em>. Si A = {1,2}, entonces 1 ∈ A y {1} ⊂ A, pero «1 ⊂ A» no significa nada.', v: 'pertenencia pertenece elemento', i: 'lg-conjuntos' },
{ t: 'Subconjunto (⊂)', d: 'A es subconjunto de B cuando todos los elementos de A están también en B. El conjunto vacío es subconjunto de todos, y todo conjunto es subconjunto de sí mismo.', v: 'subconjunto inclusion contenido', i: 'lg-conjuntos' },
{ t: 'Unión e intersección', d: 'Las dos operaciones básicas entre conjuntos. La <strong>unión</strong> (∪) reúne lo que está en uno <em>o</em> en otro; la <strong>intersección</strong> (∩) se queda solo con lo que está en los dos <em>a la vez</em>. Son el «o» y la «y» de la lógica, dibujados.', v: 'union interseccion', i: 'lg-conjuntos' },
{ t: 'Conjunto vacío (∅)', d: 'El conjunto que no tiene ningún elemento. Parece inútil y no lo es: aparece cada vez que dos cosas no tienen nada en común, y es subconjunto de cualquier conjunto.', v: 'vacio conjunto vacio', i: 'lg-conjuntos' },
{ t: 'Cardinal', d: 'El número de elementos de un conjunto; se escribe entre barras, |A|. Para conjuntos infinitos la idea se refina y da lugar a resultados sorprendentes, como que haya más números reales que naturales.', i: 'lg-conjuntos' },
{ t: 'Producto cartesiano', d: 'Dados dos conjuntos, el conjunto de todas las <em>parejas ordenadas</em> que se pueden formar tomando uno de cada. Aquí el orden importa: (1,2) no es (2,1). El plano entero es el producto cartesiano de los reales consigo mismos.', v: 'producto cartesiano pares ordenados', i: 'lg-conjuntos' },
{ t: 'Aplicación', d: 'Otro nombre de <em>función</em>: una regla que asigna a cada elemento de un conjunto <strong>exactamente uno</strong> de otro. Las dos exigencias hacen todo el trabajo: «a cada» prohíbe dejar a alguien sin asignar, y «exactamente uno» prohíbe la ambigüedad.', v: 'aplicacion funcion', i: 'lg-conjuntos' },
{ t: 'Inyectiva, sobreyectiva, biyectiva', d: 'Las tres formas de repartir de una aplicación. <strong>Inyectiva</strong>: nadie comparte destino (por eso un DNI identifica). <strong>Sobreyectiva</strong>: no sobra nadie en el conjunto de llegada. <strong>Biyectiva</strong>: las dos cosas, un emparejamiento perfecto, y por eso se puede deshacer.', v: 'inyectiva sobreyectiva biyectiva inyectividad', i: 'lg-conjuntos' },

/* ---------------- aritmética ---------------- */
{ t: 'Valor posicional', d: 'La idea de que una cifra vale distinto según el lugar que ocupa: el 3 de 300 vale trescientos y el de 3 vale tres. Es lo que hace que con diez símbolos se escriba cualquier número, y lo que permite que un ordenador cuente con solo dos.', i: 'ar-naturales' },
{ t: 'Divisor y múltiplo', d: 'Son la misma relación vista desde los dos lados: si 3 divide a 12, entonces 12 es múltiplo de 3. «Divide» significa que la división es exacta, sin resto.', v: 'divisor multiplo divisibilidad', i: 'ar-divisibilidad' },
{ t: 'Número primo', d: 'Un número mayor que 1 que solo se puede dividir exactamente por 1 y por sí mismo. Son los ladrillos con los que se construyen todos los demás por multiplicación, y su dificultad para ser recuperados de un producto sostiene el cifrado de internet. El 1 no se considera primo, por convenio útil.', v: 'primo primos', i: 'ar-divisibilidad' },
{ t: 'Factorizar', d: 'Escribir algo como un producto. Un número, como producto de primos: 60 = 2²·3·5. Un polinomio, como producto de polinomios más simples. Es la operación que permite simplificar fracciones y resolver ecuaciones, porque un producto vale cero solo si algún factor vale cero.', v: 'factorizar factorizacion descomposicion', i: 'al-identidades' },
{ t: 'm.c.d. y m.c.m.', d: 'El <strong>máximo común divisor</strong> es el número más grande que divide a varios a la vez; sirve para simplificar y para repartir sin cortar. El <strong>mínimo común múltiplo</strong> es el más pequeño que es múltiplo de todos; responde a «¿cuándo volverá a coincidir?».', v: 'mcd mcm maximo comun divisor minimo comun multiplo', i: 'ar-divisibilidad' },
{ t: 'Valor absoluto', d: 'La distancia de un número al cero, sin importar el signo: |−5| = 5. Responde a «¿cuánto me he desviado?» cuando da igual hacia qué lado, que es lo que necesita un termostato o una medida de error.', i: 'ar-enteros' },
{ t: 'Fracción irreducible', d: 'La fracción que ya no se puede simplificar más, porque numerador y denominador no comparten ningún factor. Toda fracción tiene una sola forma irreducible, y por eso es la manera canónica de dar un resultado.', v: 'irreducible simplificar fraccion', i: 'ar-fracciones' },
{ t: 'Número racional', d: 'El que se puede escribir como fracción de dos enteros. Su marca de identidad es que su expresión decimal o se corta o se repite periódicamente. Se les llama racionales por «razón», es decir, cociente, no por ser sensatos.', v: 'racional racionales fraccion', i: 'ar-conjuntos' },
{ t: 'Número irracional', d: 'El que <strong>no</strong> se puede escribir como fracción; sus decimales no acaban ni se repiten nunca. √2, π y e lo son. El folio A4 tiene los lados en razón √2, que es la única proporción que se conserva al doblar la hoja por la mitad.', v: 'irracional irracionales', i: 'ar-conjuntos' },
{ t: 'Intervalo', d: 'Un tramo de la recta real. Se escribe con corchete si el extremo entra, [2,5], y con paréntesis si no, (2,5). Fuera del aula casi nada se especifica con un número exacto sino con un intervalo: una tolerancia, un rango de referencia, un margen.', i: 'ar-conjuntos' },
{ t: 'Potencia', d: 'Una multiplicación abreviada: la <em>base</em> es lo que se repite y el <em>exponente</em>, cuántas veces. Ojo, 2⁵ no es 2·5 sino 32. Que el exponente pueda ser cero, negativo o fraccionario no es un capricho: es lo único que mantiene las propiedades sin excepciones.', v: 'potencia exponente base', i: 'ar-potencias' },
{ t: 'Raíz', d: 'La operación que deshace una potencia: la raíz enésima de a es el número que elevado a n da a. Se puede escribir como potencia de exponente fraccionario, y con eso raíces y potencias dejan de ser dos mundos.', v: 'raiz radical radicando indice', i: 'ar-potencias' },
{ t: 'Notación científica', d: 'Escribir un número como un valor entre 1 y 10 multiplicado por una potencia de diez: 0,00034 es 3,4·10⁻⁴. No sirve solo para ahorrar ceros; sirve para comparar de un vistazo, mirando solo el exponente.', v: 'notacion cientifica', i: 'ar-potencias' },
{ t: 'Cifras significativas', d: 'Las cifras de una medida que de verdad se han medido. Escribir más de las que tienes es afirmar algo que no sabes: dar una coordenada de GPS al milímetro es inventarse los últimos dígitos.', v: 'cifras significativas precision', i: 'ar-magnitudes' },
{ t: 'Análisis dimensional', d: 'Comprobar que las unidades de una fórmula cuadran antes de calcular nada. Si al despejar te queda una velocidad igualada a una aceleración, ya sabes que está mal sin revisar las cuentas. Es un detector de errores que cuesta diez segundos.', v: 'analisis dimensional unidades dimensiones', i: 'ar-magnitudes' },
{ t: 'Proporcionalidad directa e inversa', d: '<strong>Directa</strong>: al multiplicar una magnitud por un número, la otra queda multiplicada por el mismo; lo constante es el cociente. <strong>Inversa</strong>: la otra queda dividida; lo constante es el producto. Más kilos, más precio es directa; más obreros, menos tiempo es inversa.', v: 'proporcionalidad directa inversa proporcional', i: 'ar-proporcionalidad' },
{ t: 'Interés compuesto', d: 'El que se calcula no solo sobre el capital inicial sino también sobre los intereses ya generados. Es la razón de que una hipoteca larga cueste tanto más que el dinero prestado, y de que empezar a ahorrar diez años antes importe más que ahorrar el doble.', v: 'interes compuesto simple', i: 'ar-proporcionalidad' },

/* ---------------- álgebra ---------------- */
{ t: 'Incógnita', d: 'La letra que representa el número desconocido que hay que averiguar. Se distingue de un <em>parámetro</em>, que también es una letra pero representa un dato fijo aunque no se diga cuál.', v: 'incognita variable parametro', i: 'al-lenguaje' },
{ t: 'Monomio y polinomio', d: 'Un <strong>monomio</strong> es un producto de un número por potencias de letras, como 5x³. Un <strong>polinomio</strong> es una suma de monomios. Solo se pueden sumar monomios <em>semejantes</em>, los que tienen la misma parte literal, porque no se suman peras con manzanas.', v: 'monomio polinomio termino grado semejantes', i: 'al-lenguaje' },
{ t: 'Grado', d: 'De un monomio, la suma de los exponentes de sus letras. De un polinomio, el mayor grado de sus monomios. Es lo que decide el aspecto de la gráfica y cuántas soluciones puede tener una ecuación.', i: 'al-polinomios' },
{ t: 'Identidad', d: 'Una igualdad que se cumple para <strong>cualquier</strong> valor de las letras, a diferencia de una ecuación, que solo se cumple para algunos. (a+b)² = a²+2ab+b² es una identidad; x+2 = 5 es una ecuación.', v: 'identidad identidades notables igualdad', i: 'al-identidades' },
{ t: 'Discriminante', d: 'El número b²−4ac de una ecuación de segundo grado. Sin resolver nada, su signo dice cuántas soluciones hay: positivo dos, cero una doble, negativo ninguna real. Responde a «¿llega o no llega?» de forma muchísimo más barata que resolver.', i: 'al-ec2' },
{ t: 'Valores prohibidos', d: 'Los valores de la incógnita que hacen que una expresión no tenga sentido, típicamente los que anulan un denominador o dejan negativo lo de dentro de una raíz par. Localizarlos antes de operar evita respuestas falsas.', v: 'valores prohibidos dominio denominador', i: 'al-fracciones-alg' },
{ t: 'Logaritmo', d: 'La operación que responde a «¿a qué exponente hay que elevar la base para obtener este número?». Su gran virtud es que <strong>baja el exponente</strong>, y por eso es la herramienta para despejar una incógnita que está arriba. Solo existe para números positivos.', v: 'logaritmo log neperiano ln base', i: 'al-radicales-log' },
{ t: 'Sistema de ecuaciones', d: 'Varias ecuaciones que se tienen que cumplir <em>a la vez</em>. Con dos incógnitas, cada ecuación es una recta y resolver es buscar dónde se cortan; de ahí que pueda haber una solución, ninguna o infinitas.', v: 'sistema ecuaciones compatible incompatible determinado indeterminado', i: 'al-sistemas' },
{ t: 'Matriz', d: 'Una tabla rectangular de números. Pero pensarla como una tabla se queda corto: una matriz es una <strong>transformación</strong> —un giro, un estiramiento, una proyección—, y multiplicar dos matrices significa aplicar una después de la otra. De ahí sale la regla de fila por columna y de ahí que el producto no sea conmutativo.', i: 'al-matrices' },
{ t: 'Determinante', d: 'Un número que se asocia a toda matriz cuadrada y que concentra mucha información sobre ella. Su valor absoluto es el área (o el volumen) que genera la transformación; si vale cero, la transformación aplasta el espacio y ya no se puede deshacer.', i: 'al-matrices' },
{ t: 'Matriz inversa', d: 'La que deshace lo que hizo otra. Existe solo si el determinante no es cero, y esa condición tiene un significado claro: si la transformación perdió información por el camino, no hay manera de volver atrás.', v: 'inversa matriz inversa', i: 'al-matrices' },
{ t: 'Rango', d: 'El número de filas realmente independientes de una matriz, es decir, las que quedan sin anularse al escalonarla. Comparar el rango de la matriz de coeficientes con el de la ampliada es lo que decide si un sistema tiene solución.', i: 'al-gauss' },
{ t: 'Número complejo', d: 'Un número de la forma a+bi, donde i es la unidad imaginaria, definida por i² = −1. No nacieron para resolver x²+1=0 —eso se declaraba imposible— sino porque hacían falta como paso intermedio para resolver ecuaciones de tercer grado con soluciones reales.', v: 'complejo complejos imaginario binomica', i: 'al-complejos' },
{ t: 'Unidad imaginaria (i)', d: 'El número definido por i² = −1. Geométricamente, multiplicar por i es <strong>girar un cuarto de vuelta</strong>, y por eso i² = −1: dos cuartos de vuelta son media vuelta, que es lo que hace el signo menos.', v: 'unidad imaginaria i', i: 'al-complejos' },

/* ---------------- módulo: tres acepciones ---------------- */
{ t: 'Módulo (de un vector)', d: 'Su longitud, es decir, la distancia entre el origen y la punta de la flecha. Se escribe entre barras, |v⃗|, y se calcula con Pitágoras a partir de las componentes. Es una de las tres cosas que definen un vector, junto con dirección y sentido.', v: 'modulo vector longitud norma', i: 'ge-vectores' },
{ t: 'Módulo (de un complejo)', d: 'Su distancia al origen en el plano complejo: para a+bi vale √(a²+b²). Es la misma idea que el módulo de un vector, porque un complejo se dibuja como un punto del plano. Al multiplicar dos complejos, sus módulos se multiplican.', v: 'modulo complejo', i: 'al-complejos' },
{ t: 'Módulo n (aritmética modular)', d: 'Aquí «módulo» significa otra cosa: es el número entre el que se divide para quedarse solo con el resto. «15 ≡ 3 módulo 12» dice que 15 y 3 dejan el mismo resto al dividir entre 12, que es lo que ocurre en un reloj. Nada que ver con la longitud de un vector, pese al nombre.', v: 'modulo n modular congruencia resto reloj', i: 'av-numeros' },

/* ---------------- geometría y trigonometría ---------------- */
{ t: 'Semejanza', d: 'Dos figuras son semejantes cuando tienen la misma forma y distinto tamaño: ángulos iguales y lados proporcionales. La razón entre lados se llama razón de semejanza, y hay que recordar que las áreas van con su cuadrado y los volúmenes con su cubo.', v: 'semejanza semejante razon', i: 'ge-semejanza' },
{ t: 'Lugar geométrico', d: 'El conjunto de todos los puntos que cumplen una condición. La circunferencia es el lugar de los puntos que están a la misma distancia de un centro; la elipse, el de los que suman una distancia constante a dos focos. Definir así una figura permite traducirla a ecuación.', v: 'lugar geometrico', i: 'ge-conicas' },
{ t: 'Vector', d: 'Una flecha: sirve para las magnitudes que no quedan definidas con un solo número porque además tienen dirección, como la velocidad o una fuerza. Tiene módulo (longitud), dirección (la recta sobre la que va) y sentido (hacia dónde apunta de los dos posibles).', v: 'vector vectores', i: 'ge-vectores' },
{ t: 'Escalar', d: 'Un número corriente, cuando se lo quiere distinguir de un vector. La masa y la temperatura son escalares; la velocidad y la fuerza son vectores. Multiplicar un vector por un escalar lo estira o lo encoge.', i: 'ge-vectores' },
{ t: 'Producto escalar', d: 'Operación entre dos vectores que devuelve <strong>un número</strong>, no un vector. Mide cuánto van los dos en la misma dirección: positivo si apuntan hacia el mismo lado, cero si son perpendiculares, negativo si se oponen. Comprobar si vale cero es la forma más rápida de detectar un ángulo recto.', v: 'producto escalar', i: 'ge-vectores' },
{ t: 'Producto vectorial', d: 'Operación entre dos vectores del espacio que devuelve <strong>otro vector</strong>, perpendicular a los dos. Responde a «¿hacia dónde mira esta superficie?», que es lo que necesita cualquier motor gráfico para iluminar una escena, y describe el momento de una fuerza.', v: 'producto vectorial', i: 'ge-espacio' },
{ t: 'Rectas que se cruzan', d: 'En el espacio, dos rectas pueden no cortarse y tampoco ser paralelas: se cruzan, como dos calles a distinta altura. Es la posición que no tiene equivalente en el plano y la que más se olvida al pasar de dos a tres dimensiones.', v: 'se cruzan cruzan alabeadas posiciones relativas', i: 'ge-espacio' },
{ t: 'Radián', d: 'La unidad natural de ángulo: el ángulo cuyo arco mide lo mismo que el radio. Una vuelta completa son 2π radianes. No es un convenio como el grado: en radianes la longitud de arco es simplemente radio por ángulo, y la derivada del seno es el coseno. En grados aparecen factores feísimos.', v: 'radian radianes grados', i: 'tr-circunferencia' },
{ t: 'Razones trigonométricas', d: 'Seno, coseno y tangente: los cocientes entre los lados de un triángulo rectángulo. Su gracia es que solo dependen del ángulo, no del tamaño del triángulo, y por eso permiten medir alturas y distancias inalcanzables.', v: 'razones trigonometricas seno coseno tangente', i: 'tr-razones' },
{ t: 'Amplitud, frecuencia y fase', d: 'Los mandos de una onda. La <strong>amplitud</strong> es lo alto que sube (el volumen de un sonido); la <strong>frecuencia</strong>, cuántas veces se repite por segundo (lo grave o agudo); la <strong>fase</strong>, en qué punto del ciclo empieza. Con esos tres números y un desplazamiento se describe casi todo lo que oscila.', v: 'amplitud frecuencia fase periodo onda', i: 'tr-funciones' },

/* ---------------- funciones y análisis ---------------- */
{ t: 'Función', d: 'Una regla que asigna a cada valor de entrada exactamente un valor de salida. La definición moderna no exige que haya fórmula: basta con que la asignación esté bien determinada. Esa generalidad, que hoy parece obvia, fue revolucionaria en 1837.', v: 'funcion funciones', i: 'fn-concepto' },
{ t: 'Dominio y recorrido', d: 'El <strong>dominio</strong> son los valores de entrada que la función admite; el <strong>recorrido</strong>, los valores de salida que llega a alcanzar. En Bachillerato el dominio se calcula buscando lo prohibido: denominadores que se anulan, raíces pares de negativos y logaritmos de cero o menos.', v: 'dominio recorrido imagen rango', i: 'fn-concepto' },
{ t: 'Pendiente', d: 'Cuánto sube una recta por cada unidad que avanza. Es el número que aparece por todas partes disfrazado: el 12 % de una señal de tráfico, los euros por kilómetro de un taxi, el consumo por hora de un aparato.', i: 'fn-lineales' },
{ t: 'Asíntota', d: 'Una recta a la que la curva se acerca indefinidamente sin llegar a tocarla. No es un adorno del dibujo: suele ser un límite físico real, el techo al que tiende un rendimiento, una concentración o una velocidad.', v: 'asintota asintotas', i: 'fn-racionales' },
{ t: 'Progresión aritmética y geométrica', d: 'En la <strong>aritmética</strong>, cada término se obtiene <em>sumando</em> siempre lo mismo al anterior; crece en línea recta. En la <strong>geométrica</strong> se obtiene <em>multiplicando</em> siempre por lo mismo; crece de forma explosiva. La diferencia entre ambas es la diferencia entre un sueldo y un interés compuesto.', v: 'progresion aritmetica geometrica sucesion razon diferencia', i: 'fn-sucesiones' },
{ t: 'Límite', d: 'El valor al que se acerca una función cuando la variable se aproxima a un punto. Lo esencial es que <strong>no mira lo que pasa en el punto</strong>, sino hacia dónde se dirige, y por eso puede existir aunque la función ni siquiera esté definida allí. Sin esa distinción no habría derivadas.', i: 'fn-limites' },
{ t: 'Indeterminación', d: 'Una expresión como 0/0 o ∞−∞ que aparece al sustituir y que no decide nada por sí sola: no significa que el límite no exista, sino que hay que trabajar más para averiguarlo. El nombre lo dice: está sin determinar, no está prohibida.', v: 'indeterminacion indeterminaciones', i: 'fn-limites' },
{ t: 'Continuidad', d: 'Una función es continua en un punto si el límite existe, la función existe allí y además <strong>coinciden</strong>. En la práctica: se puede dibujar sin levantar el lápiz. En ingeniería los saltos rompen cosas, y por eso las curvas de una autopista no pasan de recta a círculo de golpe.', v: 'continuidad continua discontinuidad', i: 'fn-limites' },
{ t: 'Derivada', d: 'La pendiente de la recta tangente en un punto, o dicho de otro modo, el <strong>ritmo instantáneo de cambio</strong>. Las dos lecturas importan y son la misma operación: si la función es la posición, su derivada es la velocidad; si es el número de contagiados, es la velocidad de contagio.', v: 'derivada derivar derivadas', i: 'fn-derivadas' },
{ t: 'Recta tangente', d: 'La recta que toca a la curva en un punto y lleva su misma pendiente. Es la mejor aproximación recta de la curva cerca de ese punto, y de ahí que la derivada sirva para estimar.', v: 'tangente secante', i: 'fn-derivadas' },
{ t: 'Regla de la cadena', d: 'La regla para derivar una función metida dentro de otra: se deriva la de fuera dejando lo de dentro intacto y se multiplica por la derivada de lo de dentro. Es la que más cuesta y la que más se usa. Truco para no olvidar el segundo factor: pregúntate siempre si lo de dentro es simplemente x.', v: 'regla de la cadena composicion', i: 'fn-derivadas' },
{ t: 'Punto crítico', d: 'Un punto donde la derivada vale cero, es decir, donde la curva está momentáneamente llana. Es <em>candidato</em> a máximo o mínimo, no garantía: en x³ la derivada se anula en el origen y la función sigue subiendo.', v: 'punto critico extremo maximo minimo', i: 'fn-aplicaciones' },
{ t: 'Punto de inflexión', d: 'El punto donde la curva deja de doblarse hacia un lado y empieza a doblarse hacia el otro. En una epidemia es el día en que la cosa empieza a mejorar, aunque los casos totales sigan subiendo.', v: 'inflexion curvatura concava convexa', i: 'fn-aplicaciones' },
{ t: 'Optimizar', d: 'Buscar el valor máximo o mínimo de una magnitud. El método convierte «encontrar lo mejor» en «resolver una ecuación»: se escribe la magnitud en función de una variable, se deriva y se iguala a cero. Es lo que hace un GPS al buscar la ruta más corta y lo que hace una inteligencia artificial al entrenarse.', v: 'optimizar optimizacion maximo minimo', i: 'fn-aplicaciones' },
{ t: 'Primitiva', d: 'Una función cuya derivada es la que te han dado. Integrar es buscarla, es decir, deshacer una derivada. Hay infinitas primitivas de la misma función, todas iguales salvo una constante, y por eso aparece siempre el «+C».', v: 'primitiva integral indefinida constante de integracion', i: 'fn-integral-indef' },
{ t: 'Integral definida', d: 'El área encerrada entre la curva y el eje en un tramo, entendida como el límite de sumar infinitos rectangulitos cada vez más finos. La regla de Barrow es el atajo que convierte esa suma infinita en una simple resta de dos valores.', v: 'integral definida area barrow', i: 'fn-integral-def' },
{ t: 'Región factible', d: 'En programación lineal, la zona del plano donde se cumplen todas las restricciones a la vez. El óptimo está siempre en uno de sus vértices, y eso es lo que convierte un problema con infinitas posibilidades en una lista corta que revisar.', v: 'region factible programacion lineal restricciones vertices', i: 'fn-prog-lineal' },

/* ---------------- probabilidad y estadística ---------------- */
{ t: 'Suceso', d: 'Un conjunto de resultados posibles de un experimento. «Sacar par» al tirar un dado es el suceso {2,4,6}. Como son conjuntos, todo lo que sabes de uniones e intersecciones vale aquí con otro vocabulario.', v: 'suceso sucesos espacio muestral', i: 'pe-probabilidad' },
{ t: 'Regla de Laplace', d: 'Probabilidad igual a casos favorables entre casos posibles. Tiene una condición que se olvida constantemente y que es donde vive el negocio de los casinos: <strong>solo vale si todos los casos son igual de probables</strong>.', v: 'laplace favorables posibles', i: 'pe-probabilidad' },
{ t: 'Sucesos incompatibles', d: 'Los que no pueden ocurrir a la vez. No confundir con independientes: dos sucesos incompatibles son máximamente <em>dependientes</em>, porque si ocurre uno ya sabes con certeza que el otro no.', v: 'incompatibles excluyentes', i: 'pe-probabilidad' },
{ t: 'Sucesos independientes', d: 'Aquellos en los que saber que ha ocurrido uno no cambia la probabilidad del otro. Entonces, y solo entonces, la probabilidad de que ocurran los dos es el producto de las suyas.', v: 'independientes independencia', i: 'pe-condicionada' },
{ t: 'Probabilidad condicionada', d: 'La probabilidad de A <em>sabiendo que</em> ha ocurrido B; se escribe P(A|B) con una barra que se lee «sabiendo que». Enterarse de algo reduce el mundo de posibilidades, y la fórmula no hace más que recalcular dentro de ese mundo más pequeño.', v: 'condicionada condicional barra', i: 'pe-condicionada' },
{ t: 'Teorema de Bayes', d: 'La fórmula que da la vuelta a una probabilidad condicionada: pasa de «probabilidad del efecto dada la causa» a «probabilidad de la causa dado el efecto». Su conclusión desconcierta: con una enfermedad rara, la mayoría de los positivos de una prueba muy buena pueden ser falsos.', v: 'bayes teorema de bayes', i: 'pe-condicionada' },
{ t: 'Media, mediana y moda', d: 'Tres formas de resumir unos datos con un número. La <strong>media</strong> reparte el total a partes iguales; la <strong>mediana</strong> es el valor que deja la mitad a cada lado; la <strong>moda</strong> es el que más se repite. Con un dato extremo se separan muchísimo, y por eso los informes de salarios serios dan la mediana.', v: 'media mediana moda promedio centralizacion', i: 'pe-descriptiva' },
{ t: 'Varianza y desviación típica', d: 'Miden lo dispersos que están los datos respecto a su media. La <strong>varianza</strong> promedia las distancias al cuadrado; la <strong>desviación típica</strong> es su raíz, y tiene la ventaja de estar en las mismas unidades que los datos. En una inversión, la desviación es literalmente lo que se llama riesgo.', v: 'varianza desviacion tipica dispersion sigma', i: 'pe-descriptiva' },
{ t: 'Covarianza', d: 'Mide si dos variables se desvían de su media hacia el mismo lado. Tiene un defecto para comparar: depende de las unidades. El coeficiente de correlación lo arregla dividiendo por las desviaciones típicas.', i: 'pe-bidimensional' },
{ t: 'Coeficiente de correlación', d: 'Un número entre −1 y 1 que mide cuánto se parece una nube de puntos a una recta. Que valga casi cero significa que no hay relación <em>lineal</em>, no que no haya relación: los puntos de una parábola perfecta dan casi cero. Y correlación nunca implica causalidad.', v: 'correlacion pearson r', i: 'pe-bidimensional' },
{ t: 'Recta de regresión', d: 'La recta que mejor representa una nube de puntos, definida como la que hace mínima la suma de los cuadrados de las distancias verticales. Sirve para predecir, con dos cautelas: que la correlación sea alta y que no se extrapole fuera del rango observado.', v: 'regresion minimos cuadrados', i: 'pe-bidimensional' },
{ t: 'Distribución binomial', d: 'El modelo de contar éxitos en un número fijo de intentos independientes con la misma probabilidad cada uno. Es el modelo del control de calidad y de los ensayos clínicos: cuántas piezas defectuosas en un lote, cuántos pacientes mejoran de los tratados.', v: 'binomial bernoulli', i: 'pe-binomial' },
{ t: 'Distribución normal', d: 'La campana de Gauss. Aparece por todas partes por una razón profunda: cuando muchos efectos pequeños e independientes se suman, el resultado tiende a ser normal, digan lo que digan las causas por separado.', v: 'normal gauss campana', i: 'pe-normal' },
{ t: 'Tipificar', d: 'Transformar un dato en «a cuántas desviaciones típicas está de la media». Sirve para comparar cosas medidas en unidades distintas: si tu nota está a 1,5 desviaciones por encima en Matemáticas y a 0,8 en Lengua, has ido mejor en Matemáticas aunque el número fuera más bajo.', v: 'tipificar tipificacion z estandarizar', i: 'pe-normal' },
{ t: 'Intervalo de confianza', d: 'Un rango dentro del cual se estima que está el valor real, con un nivel de confianza declarado. Es el «±3 puntos» de las encuestas. Su anchura depende de la raíz del tamaño de la muestra, y por eso para reducir el error a la mitad hay que cuadruplicarla.', v: 'intervalo de confianza margen de error', i: 'pe-inferencia' },
{ t: 'Contraste de hipótesis', d: 'El procedimiento para decidir, con datos, si una afirmación se sostiene o no. Es como se aprueba un medicamento. Tiene una patología conocida: probando muchas hipótesis, alguna sale «significativa» por pura suerte.', v: 'contraste hipotesis significativo p-valor', i: 'pe-inferencia' },

/* ---------------- bloques 7 a 11: mas alla del Bachillerato ---------------- */
{ t: 'Espacio vectorial', d: 'Un conjunto donde se puede sumar y multiplicar por números respetando las reglas de siempre. Lo potente es que no habla solo de flechas: los polinomios, las matrices y las funciones forman espacios vectoriales, y por eso todo lo que demuestres aquí vale para todos ellos.', v: 'espacio vectorial base dimension', i: 'av-espacios' },
{ t: 'Base y dimensión', d: 'Una <strong>base</strong> es un conjunto mínimo de vectores con los que se puede construir todo lo demás combinándolos. La <strong>dimensión</strong> es cuántos hacen falta. Cambiar de base es lo que hace un JPEG: escribir lo mismo en un sistema donde casi todas las coordenadas salen despreciables.', v: 'base dimension independencia lineal', i: 'av-espacios' },
{ t: 'Núcleo e imagen', d: 'De una aplicación lineal, el <strong>núcleo</strong> es lo que se aplasta hasta desaparecer y la <strong>imagen</strong> es hasta dónde llega lo que sale. Si el núcleo no es trivial, distintas entradas dan la misma salida y ya no se puede volver atrás: eso es reducir la resolución de una foto.', v: 'nucleo imagen kernel rango', i: 'av-espacios' },
{ t: 'Autovalor y autovector', d: 'Un <strong>autovector</strong> es una dirección que la transformación no tuerce: solo la estira o la encoge. Cuánto la estira es su <strong>autovalor</strong>. En una estructura son sus frecuencias propias, y conocerlas es lo que evita que un puente entre en resonancia.', v: 'autovalor autovector valor propio diagonalizar', i: 'av-lineal' },
{ t: 'Cadena de Markov', d: 'Un proceso que salta entre estados donde la probabilidad del siguiente paso depende solo de dónde estás ahora, no de cómo llegaste. Su distribución estacionaria —el reparto que ya no cambia a largo plazo— es el algoritmo con el que Google ordenó la web.', v: 'markov estacionaria transicion absorbente', i: 'av-markov' },
{ t: 'Ecuación diferencial', d: 'Una ecuación cuya incógnita es una <em>función</em> y que relaciona esa función con sus derivadas. Dice cómo cambia algo, y resolverla es averiguar cómo es. Casi toda la física está escrita así, empezando por F = ma.', v: 'ecuacion diferencial edo edp', i: 'av-edo' },
{ t: 'Punto de equilibrio', d: 'Un estado en el que el sistema se queda quieto. Lo decisivo es si es <strong>estable</strong> —si al apartarlo un poco vuelve— o <strong>inestable</strong>. Un péndulo colgando es estable; el mismo péndulo invertido no lo es, y mantenerlo exige corregir cien veces por segundo.', v: 'equilibrio estable inestable', i: 'av-sistemas-dinamicos' },
{ t: 'Caos', d: 'Un sistema es caótico cuando dos estados iniciales casi idénticos acaban separándose por completo. No significa aleatorio: las reglas son deterministas. Significa impredecible en la práctica, porque nunca se conocen los datos con precisión infinita. Es la razón de que el tiempo no se pueda predecir a más de dos semanas.', v: 'caos efecto mariposa lorenz sensible', i: 'av-caos' },
{ t: 'Fractal', d: 'Una figura que se repite a distintas escalas y cuya dimensión no es un número entero. Esa dimensión fraccionaria mide rugosidad, y se usa en medicina: la ramificación de los vasos de una retina tiene una dimensión característica, y desviarse de ella es señal de enfermedad.', v: 'fractal dimension fraccionaria', i: 'av-caos' },
{ t: 'Derivada parcial', d: 'La derivada de una función de varias variables respecto a una de ellas, tratando las demás como si fueran números fijos. Se escribe con una d redondeada, ∂, para distinguirla. Responde a «si muevo solo esto, ¿cuánto cambia el resultado?».', v: 'parcial parciales', i: 'av-vectorial' },
{ t: 'Gradiente', d: 'El vector que apunta hacia donde una función crece más deprisa. Es la brújula de casi todo lo que se optimiza hoy: entrenar un modelo de inteligencia artificial consiste en calcular gradientes y caminar en sentido contrario, cuesta abajo.', v: 'gradiente nabla', i: 'av-vectorial' },
{ t: 'Divergencia y rotacional', d: 'Dos formas de interrogar a un campo vectorial. La <strong>divergencia</strong> mide cuánto sale menos cuánto entra en un punto: positiva es una fuente, negativa un sumidero. El <strong>rotacional</strong> mide cuánto tiende a girar el campo allí.', v: 'divergencia rotacional campo', i: 'av-vectorial' },
{ t: 'Serie de Fourier', d: 'La descomposición de una función periódica en suma de senos y cosenos. Su versión general, la transformada, está dentro de un MP3, de un JPEG, de una llamada de móvil y de una resonancia magnética: es probablemente la matemática que más veces se ejecuta al día en el mundo.', v: 'fourier serie transformada espectro frecuencia', i: 'av-fourier' },
{ t: 'Curvatura', d: 'Cuánto se aparta una curva de ser recta, o una superficie de ser plana. El teorema egregio de Gauss dice que la curvatura de una superficie es intrínseca, y de ahí que no exista un mapa plano fiel de la Tierra: ninguna proyección puede conservarlo todo.', v: 'curvatura gauss egregio', i: 'av-geodif' },
{ t: 'Geodésica', d: 'El camino más corto sobre una superficie curva. Sobre una esfera no es la línea recta del mapa sino un arco de círculo máximo, y por eso un vuelo de Madrid a Nueva York sube hacia Groenlandia. En relatividad, un planeta en órbita simplemente sigue su geodésica.', v: 'geodesica camino mas corto', i: 'av-geodif' },
{ t: 'Topología', d: 'El estudio de las propiedades que se conservan al deformar sin romper ni pegar. Para un topólogo, una taza y un donut son la misma cosa, porque los dos tienen un agujero. Lo que parece la rama más abstracta se usa hoy para clasificar tumores y planificar movimientos de robots.', v: 'topologia genero agujeros homeomorfo', i: 'av-topologia' },
{ t: 'Grupo', d: 'Un conjunto con una operación que cumple cuatro reglas mínimas. Sirve para estudiar simetrías: los giros de un cristal, las permutaciones de las soluciones de una ecuación. Con esta idea se demostró que no puede existir fórmula para las ecuaciones de quinto grado.', v: 'grupo grupos simetria galois', i: 'av-grupos' },
{ t: 'Numerable', d: 'Un conjunto infinito es numerable si se puede emparejar uno a uno con los números naturales, es decir, si se puede hacer una lista aunque no acabe nunca. Los racionales lo son; los reales no, y demostrarlo fue lo que abrió la puerta a distintos tamaños de infinito.', v: 'numerable cardinalidad cantor infinito', i: 'av-infinito' },
{ t: 'Grafo', d: 'Unos puntos y unas líneas que unen algunos de ellos. Nada más, y con eso se modelan una red de metro, las amistades de una red social, las páginas enlazadas de internet o las tareas de una obra con sus dependencias.', v: 'grafo vertice arista nodo', i: 'av-grafos' },
{ t: 'Entropía', d: 'La medida de la incertidumbre de una fuente de información: cuánta sorpresa hay, de media, en cada mensaje. Fija un límite exacto a cuánto se puede comprimir algo sin perder nada, y por eso un archivo ZIP ya no se puede volver a comprimir.', v: 'entropia informacion shannon', i: 'av-informacion' },
{ t: 'Equilibrio de Nash', d: 'Una combinación de estrategias en la que nadie mejora cambiando la suya en solitario. Ojo al matiz: no dice que sea la mejor situación para todos, solo que nadie tiene incentivo individual para moverse. Explica las guerras de precios y por qué cuesta tanto un acuerdo climático.', v: 'nash equilibrio juegos dilema prisionero', i: 'av-juegos' },
{ t: 'Método iterativo', d: 'El que se acerca a la solución repitiendo un paso que la mejora, en lugar de dar con ella de golpe. Bisección y Newton-Raphson lo son. Se usan cuando no hay fórmula, que es la situación normal fuera de los libros de texto.', v: 'iterativo iteracion biseccion newton raphson convergencia', i: 'av-numerico' },

/* ---------------- cibernética ---------------- */
{ t: 'Cibernética', d: 'La disciplina que estudia el control y la comunicación, con la tesis de que funcionan igual en una máquina y en un ser vivo. La bautizó Wiener en 1948 tomando la palabra griega <em>kybernetes</em>, «timonel»; de la misma raíz vienen «gobernar» y «gobierno».', v: 'cibernetica wiener kybernetes', i: 'cib-realimentacion' },
{ t: 'Realimentación', d: 'Que un sistema mida su propio resultado y use la diferencia con lo que quería para corregirse. Es la idea madre de todo el bloque, y lo que la hace rara es su circularidad: el efecto vuelve a la entrada y deja de estar claro quién es la causa de quién.', v: 'realimentacion retroalimentacion feedback bucle lazo', i: 'cib-realimentacion' },
{ t: 'Realimentación negativa', d: 'Aquella en la que la corrección se opone a la desviación, de modo que el sistema se estabiliza. Se llama negativa por el signo, no porque sea mala: es la que mantiene tu temperatura corporal y la que hace que un termostato funcione.', v: 'negativa estabiliza', i: 'cib-realimentacion' },
{ t: 'Realimentación positiva', d: 'Aquella en la que la corrección va a favor de la desviación, de modo que la amplifica. El chirrido de un micrófono junto a su altavoz, un pánico bancario o el deshielo que acelera el calentamiento. No es «mala»: es la que convierte un cambio pequeño en uno grande.', v: 'positiva amplifica circulo vicioso', i: 'cib-realimentacion' },
{ t: 'Ganancia', d: 'Cuánto corrige un regulador por cada unidad de error; suele escribirse $K$. Su efecto no es el intuitivo: subirla acelera la respuesta hasta cierto punto, y pasado ese punto aparecen sobrepaso, oscilación y descontrol.', v: 'ganancia gain K', i: 'cib-realimentacion' },
{ t: 'Caja negra', d: 'Un sistema que no se puede abrir y que solo se conoce perturbándolo y observando su respuesta. Es la situación normal, no la excepción: así se estudia un organismo, una economía o un programa ajeno. Su límite es que dos cajas que respondan igual a todo experimento posible son indistinguibles.', v: 'caja negra black box sondear', i: 'cib-caja-negra' },
{ t: 'Estado', d: 'El conjunto de datos que hay que conocer de un sistema para saber qué hará a continuación. Si desde el mismo estado a veces hace una cosa y a veces otra, no es que sea caprichoso: es que falta una variable por incluir en la descripción.', v: 'estado transicion determinado por su estado', i: 'cib-caja-negra' },
{ t: 'Variedad', d: 'El número de estados distintos que algo puede presentar. Medida en bits es $\\log_2 V$, y entonces coincide exactamente con la entropía de Shannon. Ashby insistía en que no es una propiedad del objeto sino del observador: depende de qué distinciones haga quien mira.', v: 'variedad ashby estados', i: 'cib-variedad' },
{ t: 'Ley de la variedad requerida', d: 'Para regular del todo un sistema hace falta al menos tanta variedad en el regulador como en las perturbaciones: $V_R \\ge V_D$. Suele citarse como «solo la variedad puede absorber variedad». Su consecuencia práctica es dura: si el regulador tiene menos jugadas, su porcentaje de fallo está fijado de antemano y no lo arregla esforzarse más.', v: 'variedad requerida ashby requisite variety', i: 'cib-variedad' },
{ t: 'Atenuar y amplificar', d: 'Las dos salidas a un problema de variedad. <strong>Amplificar</strong> es dar más respuestas al regulador; <strong>atenuar</strong>, reducir las situaciones que pueden presentarse. Un formulario con opciones cerradas atenúa; contratar más gente amplifica.', v: 'atenuar amplificar variedad', i: 'cib-variedad' },
{ t: 'Teorema del buen regulador', d: 'Resultado de Conant y Ashby (1970): todo regulador óptimo de un sistema contiene necesariamente un modelo de ese sistema. «Modelo» significa aquí hacer las mismas distinciones, no entender ni representar conscientemente. Su lectura práctica: si un regulador falla siempre igual, lo que le falta es una distinción, no potencia.', v: 'buen regulador conant modelo', i: 'cib-segundo-orden' },
{ t: 'Señal de error', d: 'La diferencia entre lo que se quiere y lo que hay, $e = r - y$. Es lo único que mira un controlador, hasta el punto de que no necesita saber qué está controlando. Que sea negativa significa que te has pasado.', v: 'error consigna referencia setpoint', i: 'cib-control' },
{ t: 'Controlador PID', d: 'El controlador más usado del mundo. Corrige con tres términos: el error de ahora (<strong>proporcional</strong>), el error acumulado (<strong>integral</strong>, que es la memoria) y el ritmo al que cambia (<strong>derivativo</strong>, que es la anticipación). Ajustar sus tres coeficientes se llama sintonizar.', v: 'pid proporcional integral derivativo sintonizar', i: 'cib-control' },
{ t: 'Error en régimen permanente', d: 'El hueco que queda entre el objetivo y lo conseguido cuando el sistema ya se ha estabilizado. Aparece con control solo proporcional y una carga constante, porque compensar la carga exige una corrección permanente y esa corrección exige un error permanente. Lo cierra el término integral.', v: 'regimen permanente error residual offset', i: 'cib-control' },
{ t: 'Variable esencial', d: 'Aquella que debe permanecer dentro de unos límites o el sistema no sobrevive: la temperatura corporal, el pH de la sangre, la liquidez de una empresa. Se distingue de las instrumentales, que pueden variar muchísimo y de hecho varían para proteger a las esenciales.', v: 'esencial instrumental limites', i: 'cib-homeostasis' },
{ t: 'Homeostasis', d: 'Mantener las variables esenciales dentro de sus límites pese a las perturbaciones. La palabra es del fisiólogo Cannon (1926) y significa literalmente «permanecer igual»; Ashby la convirtió en matemáticas.', v: 'homeostasis cannon equilibrio interno', i: 'cib-homeostasis' },
{ t: 'Ultraestabilidad', d: 'La propiedad de un sistema que, además de corregirse, sabe <strong>reconfigurarse</strong> cuando cambian las reglas del mundo. El homeostato de Ashby lo conseguía sorteando al azar sus coeficientes cada vez que una variable esencial se salía de rango: adaptación sin inteligencia.', v: 'ultraestable ultraestabilidad homeostato uniselector', i: 'cib-homeostasis' },
{ t: 'Retardo', d: 'El tiempo entre una acción correctora y su efecto observable. Obliga a decidir con información vieja y consume margen de estabilidad: una ganancia segura sin demora puede oscilar con ella. Su regla práctica es contraintuitiva: con retardo hay que corregir <em>menos</em> y esperar.', v: 'retardo demora desfase ducha', i: 'cib-retardos' },
{ t: 'Efecto látigo', d: 'La oscilación creciente de una cadena de suministro: una variación pequeña de la demanda se amplifica en cada eslabón por culpa de los retardos, y acaba en un vaivén de almacenes llenos y vacíos. Cuanto más lejos del cliente, más violento.', v: 'latigo bullwhip cadena suministro forrester', i: 'cib-retardos' },
{ t: 'Media móvil', d: 'El filtro más sencillo y probablemente el más usado: sustituir cada valor por el promedio de los $k$ últimos. Funciona porque la señal cambia despacio y el ruido salta sin memoria, así que se cancela solo. Su precio es el retraso, que crece con la ventana.', v: 'media movil ventana suavizado filtro', i: 'cib-filtrado' },
{ t: 'Señal y ruido', d: 'Lo medido es la suma de la señal verdadera y el ruido. Parece un despeje —restar el ruido— y no lo es, porque si el ruido se conociera no sería ruido: hay que estimarlo. Todo el problema del filtrado nace de ahí.', v: 'senal ruido snr', i: 'cib-filtrado' },
{ t: 'Filtro de Kalman', d: 'Método de 1960 que combina medidas ruidosas con un modelo de cómo se mueve lo medido, y produce una estimación mejor que cualquiera de los dos por separado. Lo adoptó la NASA para el programa Apolo y hoy va dentro de cada GPS: es la razón de que el punto azul siga avanzando con sensatez al entrar en un túnel.', v: 'kalman filtro apolo gps prediccion', i: 'cib-filtrado' },
{ t: 'Autómata celular', d: 'Una cuadrícula de celdas encendidas o apagadas con una regla que solo mira a las vecinas. Con vecindad de tres celdas hay exactamente 256 reglas, y se pueden explorar todas. La regla 110 resultó ser capaz de computar cualquier cosa que compute un ordenador.', v: 'automata celular regla 110 regla 30 vida conway', i: 'cib-autoorganizacion' },
{ t: 'Emergencia', d: 'Que el conjunto tenga propiedades que no están en las piezas ni en las reglas. En el Juego de la Vida ninguna celda se mueve nunca —solo se encienden y se apagan— y sin embargo hay figuras que se desplazan. No es magia: es que saber las reglas no es lo mismo que saber sus consecuencias.', v: 'emergencia emergente autoorganizacion planeador', i: 'cib-autoorganizacion' },
{ t: 'Cibernética de segundo orden', d: 'La que incluye al observador dentro del sistema observado, frente a la de primer orden, que lo deja fuera. La formuló von Foerster: la primera es la cibernética de los sistemas observados; la segunda, la de los sistemas observadores.', v: 'segundo orden von foerster observador', i: 'cib-segundo-orden' },
{ t: 'Ley de Goodhart', d: 'Cuando una medida se convierte en objetivo, deja de ser una buena medida. Si se evalúa un hospital por el tiempo de espera, el tiempo de espera mejora y deja de informar sobre la calidad. Es el acoplamiento entre observador y observado, visto en la práctica.', v: 'goodhart indicador objetivo metrica', i: 'cib-segundo-orden' },
/* ---------------- series y convergencia ---------------- */
{ t: 'Serie', d: 'La suma de los infinitos términos de una sucesión. Ojo: no es una suma de verdad, porque nadie suma infinitas cosas. Es el <em>límite</em> de las sumas parciales, y solo significa algo cuando ese límite existe.', v: 'serie suma infinita sumatorio infinito', i: 'fn-series' },
{ t: 'Suma parcial', d: 'Lo que llevas sumado hasta el término n: $S_n = a_1 + a_2 + \\dots + a_n$. Es una suma corriente, con un número finito de sumandos. Las sumas parciales forman una sucesión, y preguntarle a esa sucesión adónde va es lo único que se hace al estudiar una serie.', v: 'suma parcial parciales sn', i: 'fn-series' },
{ t: 'Convergencia', d: 'Que algo se acerca a un valor concreto y se queda ahí. Una <strong>sucesión</strong> converge si sus términos se aproximan a un número; una <strong>serie</strong> converge si lo hacen sus sumas parciales, y entonces ese límite <em>es</em> la suma de la serie. Si no converge, se dice que diverge, y la serie no tiene suma: no es que sea difícil de calcular, es que no hay ningún número que merezca ese nombre.', v: 'convergencia converge convergente convergen', i: 'fn-series' },
{ t: 'Divergencia', d: 'Lo contrario de converger. Una serie diverge si sus sumas parciales se van al infinito o si no se deciden por ningún valor. El caso más instructivo es la serie armónica: sus términos tienden a cero y aun así la suma crece sin techo.', v: 'divergencia diverge divergente divergen', i: 'fn-series' },
{ t: 'Serie armónica', d: 'La serie $1 + \\frac12 + \\frac13 + \\frac14 + \\dots$. <strong>Diverge</strong>, aunque sus términos tiendan a cero, y esa es la razón de que no se pueda concluir que una serie converge solo porque sus términos se hagan pequeños. Lo demostró Oresme hacia 1350 agrupando los términos en bloques que doblan de tamaño: cada bloque suma más de un medio.', v: 'armonica serie armonica oresme', i: 'fn-series' },
{ t: 'p-serie', d: 'La familia $\\sum \\frac{1}{n^p}$. Converge exactamente cuando $p > 1$ y diverge cuando $p \\le 1$. Es la vara de medir con la que se compara casi cualquier otra serie: se mira el término dominante y se decide de qué lado de esa frontera cae.', v: 'p serie pserie p-serie', i: 'fn-series' },
{ t: 'Serie telescópica', d: 'Aquella en la que cada término cancela parte del siguiente, de modo que la suma parcial se pliega como un catalejo y solo sobreviven el primer trozo y el último. Es la única familia en la que se ve directamente cuánto vale $S_n$, sin criterios ni trucos.', v: 'telescopica telescopio', i: 'fn-series' },
{ t: 'Serie alternada', d: 'Aquella cuyos términos van cambiando de signo. Si los valores absolutos decrecen hasta cero, converge, aunque la serie de los valores absolutos diverja. Su ventaja práctica: al cortarla, el error es siempre menor que el primer término que has dejado fuera.', v: 'alternada alternante leibniz', i: 'fn-series' },
{ t: 'Condición necesaria de convergencia', d: 'Si una serie converge, sus términos tienen que tender a cero. Se usa siempre al revés: si <em>no</em> tienden a cero, la serie no converge y se acabó el análisis. Lo que no se puede hacer nunca es leerla en el otro sentido: que tiendan a cero no garantiza nada.', v: 'condicion necesaria termino general tiende a cero', i: 'fn-series' },

/* ---------------- Taylor ---------------- */
{ t: 'Polinomio de Taylor', d: 'El polinomio de grado n que en un punto tiene exactamente las mismas derivadas que la función, hasta la de orden n. Sirve para sustituir una función complicada por una que solo tiene sumas y productos, que es lo único que sabe hacer una máquina. De grado 1 es la recta tangente de siempre.', v: 'taylor polinomio de taylor', i: 'fn-taylor' },
{ t: 'Serie de Taylor', d: 'El polinomio de Taylor llevado al infinito: $\\sum \\frac{f^{(n)}(a)}{n!}(x-a)^n$. Solo tiene sentido donde esa serie converge, y ese es exactamente el problema que estudia el tema de series numéricas.', v: 'serie de taylor maclaurin', i: 'fn-taylor' },
{ t: 'Polinomio de Maclaurin', d: 'El polinomio de Taylor centrado en el punto $a = 0$. No es un concepto distinto, solo el caso más usado, porque cerca de cero las cuentas salen más limpias.', v: 'maclaurin', i: 'fn-taylor' },
{ t: 'Resto de Lagrange', d: 'La diferencia exacta entre una función y su polinomio de Taylor: $R_n = \\frac{f^{(n+1)}(c)}{(n+1)!}(x-a)^{n+1}$, para algún punto $c$ entre $a$ y $x$. Nadie sabe cuál es ese $c$, y da igual: basta con acotar la derivada en el intervalo para <strong>garantizar</strong> cuántas cifras son correctas. Sin él, una aproximación sirve para dibujar pero no para calcular.', v: 'resto lagrange error de taylor cota del error', i: 'fn-taylor' },
{ t: 'Radio de convergencia', d: 'La distancia alrededor del punto de apoyo dentro de la cual la serie de Taylor converge. Fuera de ese radio no es que la aproximación sea mala: es que la serie no suma nada. Para $e^x$, el seno y el coseno el radio es infinito; para $\\frac{1}{1-x}$ vale 1.', v: 'radio de convergencia', i: 'fn-taylor' },
{ t: 'Derivada n-ésima', d: 'El resultado de derivar n veces seguidas. Se escribe $f^{(n)}$, con el número entre paréntesis para que no se confunda con una potencia: $f^{(3)}$ es la tercera derivada y $f^3$ es la función al cubo. Para las primeras se siguen usando las comillas.', v: 'derivada n-esima enesima orden superior', i: 'fn-taylor' },
{ t: 'Teorema de Rolle', d: 'Si una función continua y derivable sale de una altura y vuelve a la misma altura, en algún punto de en medio su tangente es horizontal. Es un teorema de existencia: dice que ese punto hay, no cuál es ni cuántos.', v: 'rolle', i: 'fn-derivadas' },
{ t: 'Teorema del valor medio', d: 'Rolle inclinado: en algún punto la pendiente instantánea coincide con la pendiente media del tramo. Si has hecho 180 km en dos horas, en algún instante ibas exactamente a 90 km/h. Es la base de los radares de tramo y del resto de Lagrange.', v: 'valor medio lagrange teorema del valor medio tvm', i: 'fn-derivadas' },

/* ---------------- matematica financiera ---------------- */
{ t: 'Valor actual', d: 'Lo que vale hoy una cantidad de dinero que se cobrará en el futuro: $VA = \\frac{C_n}{(1+i)^n}$. La operación se llama <em>descontar</em>, y es imprescindible porque sumar euros de años distintos sin traerlos a la misma fecha es como sumar metros y segundos.', v: 'valor actual descuento descontar', i: 'fn-finanzas' },
{ t: 'TIN y TAE', d: 'El <strong>TIN</strong> es el tipo nominal, el número grande del anuncio; no tiene en cuenta cada cuánto se cobran los intereses, así que no sirve para comparar. La <strong>TAE</strong> es lo que el dinero cuesta de verdad en un año, incluyendo la frecuencia de cobro y las comisiones obligatorias. Compara siempre TAE con TAE.', v: 'tin tae tipo nominal tasa anual equivalente', i: 'fn-finanzas' },
{ t: 'Cuota (sistema francés)', d: 'El pago constante con el que se devuelve un préstamo: $c = P\\frac{i}{1-(1+i)^{-n}}$. Sale de igualar el capital prestado a la suma de todas las cuotas traídas a hoy, que es una progresión geométrica. Al principio casi toda la cuota son intereses y al final casi todo es capital.', v: 'cuota hipoteca amortizacion sistema frances prestamo', i: 'fn-finanzas' },

/* ---------------- variables continuas ---------------- */
{ t: 'Variable aleatoria continua', d: 'Aquella que puede tomar cualquier valor de un intervalo, como una estatura o un tiempo de espera. La diferencia práctica con una discreta es radical: la probabilidad de un valor concreto es <strong>cero</strong>, y las únicas preguntas con sentido son sobre intervalos.', v: 'variable continua aleatoria continua', i: 'pe-continuas' },
{ t: 'Función de densidad', d: 'La curva $f$ cuya área bajo un tramo da la probabilidad de caer en ese tramo. Cumple dos cosas y nada más: no es negativa y encierra área total 1. <strong>No</strong> es una probabilidad y puede valer más de 1; lo que nunca pasa de 1 es el área. La palabra correcta es la de la física: densidad, no masa.', v: 'densidad funcion de densidad', i: 'pe-continuas' },
{ t: 'Función de distribución', d: 'La que acumula toda la probabilidad que hay a la izquierda: $F(x) = P(X \\le x)$. Con ella cualquier probabilidad es una resta, $P(a \\le X \\le b) = F(b)-F(a)$, que es la regla de Barrow con otro nombre. Y su derivada es la densidad.', v: 'funcion de distribucion acumulada', i: 'pe-continuas' },
{ t: 'Distribución uniforme', d: 'Aquella en la que todos los valores de un intervalo son igual de probables. Su densidad es una meseta plana de altura $\\frac{1}{b-a}$, forzada por que el área tenga que valer 1. Es la que genera un ordenador al pedir un número al azar.', v: 'uniforme distribucion uniforme', i: 'pe-continuas' },
{ t: 'Distribución exponencial', d: 'Modela el tiempo hasta que ocurre algo que no envejece: la desintegración de un átomo, la avería de un componente, la siguiente llamada a una centralita. Su media es $1/\\lambda$ y <strong>no tiene memoria</strong>: una bombilla que lleva mil horas encendida tiene la misma expectativa que una nueva.', v: 'exponencial sin memoria lambda', i: 'pe-continuas' },

/* ---------------- inferencia causal ---------------- */
{ t: 'Variable de confusión', d: 'Una tercera variable que influye a la vez sobre la causa supuesta y sobre el efecto supuesto, y que por tanto los hace aparecer correlacionados sin que uno cause el otro. Su firma es inconfundible: la correlación es real, los datos son correctos y la conclusión es falsa. El calor detrás de los helados y los ahogamientos.', v: 'confusion confusora tercera variable confundidora', i: 'pe-causal' },
{ t: 'Paradoja de Simpson', d: 'El caso extremo de confusión: una asociación puede invertirse al separar los datos por una tercera variable. Un tratamiento puede ser mejor para los casos fáciles, mejor para los difíciles y peor en el total, si no se ha repartido por igual entre unos y otros.', v: 'simpson paradoja de simpson', i: 'pe-causal' },
{ t: 'Aleatorización', d: 'Repartir a los participantes entre los grupos echándolo a suertes. Parece frívolo y es lo único que equilibra <strong>todas</strong> las variables de confusión, incluidas las que nadie ha medido ni pensado: la moneda no sabe nada de ellas, así que no puede favorecer a ninguna. No hace los grupos idénticos, los hace comparables.', v: 'aleatorizacion aleatorizar sorteo azar ensayo aleatorizado', i: 'pe-causal' },
{ t: 'Grupo de control', d: 'El grupo que no recibe el tratamiento y sirve de comparación. Sin él no se sabe qué habría pasado igualmente, y mucha gente mejora sola: casi toda la tos se cura en diez días con jarabe o sin él.', v: 'control grupo de control testigo', i: 'pe-causal' },
{ t: 'Placebo y doble ciego', d: 'El <strong>placebo</strong> es un tratamiento sin principio activo, y sirve para separar el efecto del fármaco del efecto de creerse tratado, que es real y medible. El <strong>doble ciego</strong> añade que tampoco quien evalúa sabe qué ha recibido cada uno, para que no sesgue la medición sin querer.', v: 'placebo ciego doble ciego cegamiento', i: 'pe-causal' },
{ t: 'Sesgo de selección', d: 'El que aparece cuando los datos que tienes han pasado por un filtro que los relaciona con lo que quieres medir. El ejemplo clásico son los aviones que vuelven del combate con impactos en las alas: no es que las alas sean lo vulnerable, es que los alcanzados en el motor no volvieron.', v: 'seleccion sesgo superviviente supervivencia wald', i: 'pe-causal' },
{ t: 'Experimento natural', d: 'Una situación en la que algo parecido a un sorteo ha ocurrido por su cuenta: una ley que entra en vigor en una región y no en la vecina, una lotería que decide quién hace el servicio militar. Es el recurso cuando aleatorizar es imposible o inaceptable.', v: 'experimento natural cuasiexperimento', i: 'pe-causal' },

/* ---------------- completitud de los reales ---------------- */
{ t: 'Cota superior', d: 'Un número que ningún elemento del conjunto supera. Un conjunto puede tener infinitas cotas o ninguna; si tiene al menos una, se dice que está acotado superiormente.', v: 'cota superior acotado cota', i: 'av-reales' },
{ t: 'Supremo', d: 'La <strong>menor</strong> de las cotas superiores de un conjunto: su borde por arriba, pertenezca o no al conjunto. El intervalo $[0,1)$ no tiene máximo y sin embargo su supremo es 1. Cuando el supremo pertenece al conjunto, coincide con el máximo.', v: 'supremo sup extremo superior', i: 'av-reales' },
{ t: 'Ínfimo', d: 'La mayor de las cotas inferiores: el borde por abajo. El conjunto $\\{1, \\frac12, \\frac13, \\dots\\}$ tiene ínfimo 0 aunque ningún elemento valga 0, y eso es exactamente lo que significa que su límite sea cero.', v: 'infimo inf extremo inferior', i: 'av-reales' },
{ t: 'Completitud', d: 'La propiedad que distingue $\\mathbb{R}$ de $\\mathbb{Q}$: todo conjunto no vacío y acotado superiormente tiene supremo. Dicho en corto, que la recta real <strong>no tiene agujeros</strong>. Sin ella se caen Bolzano, el teorema del valor intermedio, la convergencia de las sucesiones monótonas acotadas y la bisección: es decir, todo el análisis.', v: 'completitud completo axioma del supremo', i: 'av-reales' },
{ t: 'Denso', d: 'Un conjunto es denso si entre dos elementos cualesquiera hay siempre otro. Los racionales lo son, y aun así están llenos de huecos: $\\sqrt2$ falta. Denso y completo son cosas distintas, y confundirlas es el error habitual.', v: 'denso densidad de los racionales', i: 'av-reales' },

/* ---------------- computabilidad ---------------- */
{ t: 'Máquina de Turing', d: 'El modelo más simple de «calcular»: una cinta infinita, un cabezal que lee y escribe, un estado interno y una tabla finita de reglas. No tiene memoria, ni aritmética, ni bucles, y aun así no se conoce nada calculable que no pueda calcular. Tu ordenador es más rápido, no más potente.', v: 'turing maquina de turing', i: 'av-computabilidad' },
{ t: 'Tesis de Church-Turing', d: 'La convicción de que la máquina de Turing captura exactamente la noción intuitiva de «calculable». No es un teorema, porque «calculable a mano» no es un concepto matemático; es una hipótesis apoyada en que cuatro formalismos que no se parecen en nada definen la misma clase de funciones.', v: 'church turing tesis', i: 'av-computabilidad' },
{ t: 'Problema de la parada', d: 'Decidir si un programa dado, con una entrada dada, terminará alguna vez. Turing demostró en 1936 que <strong>no existe</strong> ningún programa que lo resuelva siempre, y lo hizo con el argumento diagonal de Cantor: construyendo un programa que hace lo contrario de lo que el oráculo predice de él mismo.', v: 'parada halting problema de la parada', i: 'av-computabilidad' },
{ t: 'Decidible e indecidible', d: 'Un problema es <strong>decidible</strong> si existe un algoritmo que siempre responde bien y siempre termina. Regla práctica: si la pregunta es sobre cómo está escrito un programa, suele ser decidible; si es sobre qué hace al ejecutarse, casi nunca lo es.', v: 'decidible indecidible decidibilidad', i: 'av-computabilidad' },
{ t: 'Teorema de Rice', d: 'Generaliza el problema de la parada de la peor manera posible: <em>cualquier</em> propiedad no trivial sobre el comportamiento de un programa es indecidible. Saber si dos programas hacen lo mismo, o si alguno devuelve un número negativo, no se puede decidir en general.', v: 'rice teorema de rice', i: 'av-computabilidad' },
{ t: 'Teoremas de incompletitud', d: 'Los dos resultados de Gödel de 1931. El primero: en todo sistema consistente que hable de aritmética hay afirmaciones verdaderas que no se pueden demostrar dentro de él. El segundo: entre ellas está su propia consistencia. No dicen que las matemáticas fallen, sino que no puede haber una garantía mecánica y definitiva desde dentro.', v: 'godel incompletitud gödel', i: 'av-computabilidad' },
{ t: 'Máquina universal', d: 'Una máquina de Turing capaz de simular a cualquier otra leyendo su descripción de la cinta. Turing la construyó para demostrar un teorema negativo y resultó ser la idea de <strong>ordenador de programa almacenado</strong>: un aparato cuyo comportamiento no está en el hardware sino en unos datos.', v: 'maquina universal programa almacenado', i: 'av-computabilidad' },

/* ---------------- geometrias no euclideas ---------------- */
{ t: 'Quinto postulado', d: 'El axioma de Euclides sobre las paralelas: por un punto exterior a una recta pasa una y solo una paralela. Es <strong>independiente</strong> de los otros cuatro —no se puede demostrar ni refutar desde ellos—, y negarlo produce geometrías igual de coherentes. Se tardó dos mil años en aceptarlo.', v: 'quinto postulado paralelas playfair euclides', i: 'av-noeuclidea' },
{ t: 'Geometría hiperbólica', d: 'Aquella en la que por un punto exterior a una recta pasan infinitas paralelas. Los ángulos de un triángulo suman menos de 180°, no hay rectángulos y no hay figuras semejantes de distinto tamaño. Su curvatura es negativa: la forma de una silla de montar.', v: 'hiperbolica lobachevski bolyai', i: 'av-noeuclidea' },
{ t: 'Geometría elíptica', d: 'Aquella en la que no hay paralelas: dos rectas cualesquiera se cortan. Su modelo es la esfera, donde las «rectas» son los círculos máximos y los ángulos de un triángulo suman más de 180°. Curvatura positiva.', v: 'eliptica esferica riemann circulo maximo', i: 'av-noeuclidea' },
{ t: 'Exceso esférico', d: 'Lo que la suma de los ángulos de un triángulo esférico se pasa de 180°. Cumple $\\alpha+\\beta+\\gamma-\\pi = A/R^2$: el exceso <strong>mide el área</strong>. En un triángulo pequeño comparado con la esfera es casi cero, y por eso a escala humana la Tierra parece plana.', v: 'exceso esferico triangulo esferico', i: 'av-noeuclidea' },
{ t: 'Disco de Poincaré', d: 'Un modelo del plano hiperbólico dentro de un círculo euclídeo: las rectas son arcos perpendiculares al borde, y el borde está infinitamente lejos. Es la geometría de los grabados <em>Límite circular</em> de Escher, y la que mejor representa la estructura de las redes.', v: 'poincare disco modelo hiperbolico escher', i: 'av-noeuclidea' },

/* ---------------- añadidos tras la revisión ---------------- */
{ t: 'Esperanza', d: 'La media de una variable aleatoria: el valor alrededor del cual se reparte. Se escribe $E[X]$, con corchetes, porque no se aplica a un número sino a la variable entera. En una variable discreta es la suma de cada valor por su probabilidad; en una continua, la integral de $x\\,f(x)$. Físicamente es el centro de gravedad de la distribución: el punto donde se sostendría en equilibrio.', v: 'esperanza valor esperado media e de x centro de gravedad', i: 'pe-continuas' },
{ t: 'Tanto por uno', d: 'La forma de escribir un porcentaje como número decimal: un 3 % es 0,03. Todas las fórmulas financieras lo usan así, y meter el 3 en lugar del 0,03 es el error más repetido del tema. Para pasar de porcentaje a tanto por uno se divide entre 100.', v: 'tanto por uno porcentaje tipo interes', i: 'fn-finanzas' },
{ t: 'Registro previo', d: 'Declarar públicamente, antes de mirar los datos, qué se va a medir y cómo. Impide el juego de medir veinte variables y publicar la única que salió significativa: con veinte pruebas al 5 %, una sale por puro azar. Su ausencia explica buena parte de los resultados científicos que luego no se han podido reproducir.', v: 'registro previo preregistro multiples comparaciones', i: 'pe-causal' },
{ t: 'Factorial', d: 'El producto de todos los enteros desde 1 hasta n, y se escribe $n!$: $5! = 5\\cdot4\\cdot3\\cdot2\\cdot1 = 120$. Aparece en combinatoria, al contar ordenaciones, y en los polinomios de Taylor, donde deshace el número que la derivada va multiplicando. Crece más deprisa que cualquier potencia, y por eso las series con factoriales en el denominador convergen tan bien.', v: 'factorial n! exclamacion', i: 'pe-combinatoria' },

/* ---------------- programación gráfica ---------------- */
{ t: 'Shader', d: 'Un programa que se ejecuta dentro de la tarjeta gráfica. El tipo que usa este curso, el <em>fragment shader</em>, contesta una sola pregunta: dado un píxel, ¿de qué color es? Se ejecuta una vez por píxel, millones de veces por imagen y todas a la vez, sin que ninguna sepa nada de las demás.', v: 'shader sombreador fragment shader pixel shader', i: 'gfx-pixel' },
{ t: 'GLSL', d: 'El lenguaje en que se escriben los shaders de OpenGL y de la web. Se parece a C, pero con tipos para vectores y matrices pequeños —<code>vec2</code>, <code>vec3</code>, <code>mat2</code>— y con las operaciones aritméticas definidas componente a componente.', v: 'glsl lenguaje de sombreado opengl webgl', i: 'gfx-pixel' },
{ t: 'Uniform', d: 'Un valor que el programa de fuera le pasa al shader y que es <strong>el mismo para todos los píxeles</strong> de una imagen: el tiempo, el tamaño de la ventana, la posición de un mando. De ahí el nombre. Un píxel puede leerlo pero no cambiarlo.', v: 'uniform uniforme parametro', i: 'gfx-tiempo' },
{ t: 'Coordenada normalizada', d: 'La coordenada del píxel dividida entre el tamaño de la ventana, para que el shader no dependa de la resolución. Dividir las dos componentes entre la <em>altura</em> (y no cada una por la suya) es lo que evita que los círculos salgan ovalados.', v: 'coordenada normalizada uv relacion de aspecto', i: 'gfx-coordenadas' },
{ t: 'Campo de distancia con signo', d: 'Una función que, dado un punto, devuelve la distancia a la superficie de una figura: negativa dentro, positiva fuera y cero justo en el borde. Define la figura entera con una fórmula, sin guardar ni un vértice, y las operaciones de conjuntos se traducen a <code>min</code>, <code>max</code> y un signo menos.', v: 'sdf campo de distancia distancia con signo signed distance function', i: 'gfx-distancia' },
{ t: 'smoothstep', d: 'Una función que pasa de 0 a 1 suavemente entre dos valores, con pendiente nula en los dos extremos: $t^2(3-2t)$. Es lo que convierte un borde dentado en un borde limpio, y también lo que borra las costuras al interpolar ruido.', v: 'smoothstep suavizado interpolacion suave', i: 'gfx-distancia' },
{ t: 'Plegar el espacio', d: 'Aplicar <code>fract</code> o <code>mod</code> a la coordenada antes de dibujar, de modo que una sola figura aparezca infinitas veces. No se repite el objeto: se repite el dominio, y por eso mil copias cuestan lo mismo que una.', v: 'plegar repetir dominio fract mod repeticion', i: 'gfx-repetir' },
{ t: 'Paleta de cosenos', d: 'Una manera de convertir un número en color con tres cosenos desfasados, uno por canal: $\\vec{a} + \\vec{b}\\cos(2\\pi(\\vec{f}t + \\vec{d}))$. Doce números describen una paleta entera, sin tabla ni imagen. El desfase entre canales es lo que decide el tono.', v: 'paleta de cosenos paleta color coseno iquilez', i: 'gfx-color' },
{ t: 'Gamma', d: 'La curva no lineal que relaciona el número guardado en una imagen con la luz que emite la pantalla, aproximadamente una potencia de 2,2. Su consecuencia práctica es que <strong>los colores hay que mezclarlos en luz, no en valores</strong>: promediar directamente da mezclas apagadas, y el gris que parece la mitad es 0,73 y no 0,5.', v: 'gamma correccion de gamma srgb espacio lineal', i: 'gfx-color' },
{ t: 'Hash', d: 'Una función que convierte una entrada en un número que parece aleatorio pero es siempre el mismo para la misma entrada. En gráficos es lo que permite tener azar sin memoria: cada punto del plano sortea su propio número y lo vuelve a sortear igual la próxima vez.', v: 'hash azar reproducible pseudoaleatorio semilla', i: 'gfx-ruido' },
{ t: 'Ruido de valor', d: 'Ruido suave que se obtiene sorteando un número en los vértices de una rejilla e interpolando por dentro con una curva suave. Es el pariente sencillo del ruido de Perlin, que interpola gradientes en vez de valores.', v: 'ruido de valor value noise perlin ruido suave', i: 'gfx-ruido' },
{ t: 'fbm', d: 'Ruido browniano fraccionario: la suma de varias capas de ruido, cada una al doble de frecuencia y con menos amplitud. Cada capa se llama <strong>octava</strong>, y las amplitudes forman una serie geométrica cuya razón —la <em>ganancia</em>— decide si la textura sale algodonosa o áspera. Es el generador de nubes, humo, terreno y mármol.', v: 'fbm ruido fractal octavas browniano fraccionario ganancia', i: 'gfx-ruido' },
{ t: 'Deformación del dominio', d: 'Evaluar una función en un sitio distinto del que toca: $F(p + g(p))$. La función que dibuja no se entera de nada, y según qué sea $g$ salen ondas, remolinos, lentes o humo. Aplicada dos veces —torcer con lo ya torcido— es la receta detrás de buena parte del arte generativo.', v: 'deformacion del dominio domain warping torsion warp', i: 'gfx-warp' },
{ t: 'Voronoi', d: 'El reparto del plano en celdas según cuál de unos puntos sembrados queda más cerca. Las fronteras son mediatrices, y el patrón aparece en las manchas de una jirafa, el barro seco, la espuma y el reparto de las galaxias. En un shader se calcula sembrando un punto por celda y mirando las nueve celdas vecinas.', v: 'voronoi worley ruido celular celdas delaunay', i: 'gfx-voronoi' },
{ t: 'Derivada de pantalla', d: 'La diferencia entre el valor de una variable en un píxel y en el de al lado, que la tarjeta puede dar porque procesa los píxeles en cuadros de dos por dos. <code>fwidth</code> devuelve cuánto cambia algo en un píxel, y usarla como anchura del suavizado da un borde perfecto a cualquier escala.', v: 'dfdx dfdy fwidth derivada de pantalla derivadas del hardware', i: 'gfx-derivadas' },
{ t: 'Raymarching', d: 'Técnica para dibujar en tres dimensiones sin triángulos: por cada píxel se lanza un rayo y se avanza, en cada paso, exactamente la distancia que el campo declara. Es seguro porque no hay nada más cerca que eso, y converge en veinte o treinta pasos. También se llama <em>sphere tracing</em>.', v: 'raymarching sphere tracing trazado de rayos marcha de rayos', i: 'gfx-raymarching' },
{ t: 'Normal', d: 'La dirección perpendicular a una superficie en un punto, que es lo que decide cuánta luz recibe. En un campo de distancias se obtiene calculando el <strong>gradiente</strong>, preguntando un poquito a cada lado en cada eje: no hay que derivar nada a mano.', v: 'normal vector normal gradiente perpendicular superficie', i: 'gfx-raymarching' },
{ t: 'Mínimo suave', d: 'Una versión del <code>min</code> que, en vez de dejar una arista donde dos cuerpos se cruzan, forma un cuello suave. Interpola entre los dos valores y además resta un pellizco proporcional a la anchura de fusión. Es la herramienta que convierte dos esferas pegadas en una gota de mercurio.', v: 'smin minimo suave union suave fusion blob', i: 'gfx-escena' },
{ t: 'Oclusión ambiental', d: 'El oscurecimiento de los rincones, que no es una sombra sino que allí <em>llega menos cielo</em>. Con un campo de distancias se calcula dando unos pasitos por la normal y comparando lo que dice el campo con lo que se ha avanzado. Es lo que hace que un objeto parezca apoyado en el suelo y no flotando.', v: 'oclusion ambiental ambient occlusion ao rincones', i: 'gfx-luz' },
{ t: 'Fresnel', d: 'El hecho de que una superficie refleje mucho más cuando se mira de refilán que de frente. Un charco a tus pies apenas refleja y a veinte metros parece un espejo. En shaders se aproxima con una quinta potencia, y es lo que ilumina los bordes de los objetos.', v: 'fresnel schlick reflectancia borde', i: 'gfx-luz' },
{ t: 'Compresión de tono', d: 'Meter valores de brillo mayores que 1 dentro del rango que la pantalla puede mostrar, sin recortarlos. La forma más simple es $c/(1+c)$, que deja los oscuros casi intactos y va apretando los claros. Sin ella, todo lo que se pasa de 1 se convierte en un manchón blanco plano.', v: 'compresion de tono tone mapping reinhard rango dinamico hdr', i: 'gfx-post' },
{ t: 'Tramado', d: 'Añadir a propósito menos de medio escalón de ruido antes de cuantizar, para que los píxeles de una misma banda caigan a un lado y a otro y el ojo promedie el valor intermedio. Cambia una banda visible por un ruido que no se ve, y es lo que salva los degradados oscuros.', v: 'tramado dithering bandas banding cuantizacion', i: 'gfx-post' },
{ t: 'Demoscene', d: 'La cultura, nacida a mediados de los ochenta, de escribir programas cuyo único fin es producir imagen y sonido en tiempo real, a menudo con límites de tamaño extremos (64 o 4 kilobytes). De ahí salieron el túnel, las plasmas y buena parte de las técnicas de este bloque. Alemania la declaró patrimonio cultural inmaterial en 2020.', v: 'demoscene demo intro 4k 64k pouet', i: 'gfx-directo' },

/* ---------------- 2.º de Bachillerato ---------------- */
{ t: 'Teorema de Rouché-Fröbenius', d: 'El criterio que clasifica un sistema de ecuaciones lineales mirando rangos. Si el rango de la matriz de coeficientes y el de la ampliada son distintos, el sistema es <strong>incompatible</strong>. Si coinciden y valen tanto como el número de incógnitas, tiene solución única; si coinciden pero son menores, infinitas. Primero se comparan los rangos entre sí, y solo después con las incógnitas.', v: 'rouche frobenius discusion sistema compatible incompatible determinado indeterminado', i: 'al-discusion' },
{ t: 'Matriz adjunta', d: 'La matriz que se forma sustituyendo cada elemento por su adjunto: el determinante de lo que queda al tachar su fila y su columna, con signo alterno. Traspuesta y dividida por el determinante da la inversa. Es cómoda para matrices 3×3; para matrices grandes, el método de Gauss es mucho más rápido.', v: 'adjunta adjuntos cofactores matriz de adjuntos', i: 'al-inversa' },
{ t: 'Producto mixto', d: 'El número $\\vec u\\cdot(\\vec v\\times\\vec w)$, que es el determinante de los tres vectores puestos en filas. Su valor absoluto es el volumen del paralelepípedo que forman, y vale cero exactamente cuando los tres vectores están en un mismo plano.', v: 'producto mixto volumen paralelepipedo coplanarios', i: 'ge-espacio-vectores' },
{ t: 'Vector normal', d: 'Un vector perpendicular a un plano. En la ecuación $Ax + By + Cz + D = 0$, los coeficientes $(A, B, C)$ son un vector normal. Con él se calculan ángulos entre planos, distancias de un punto a un plano y la recta perpendicular a un plano.', v: 'vector normal perpendicular plano', i: 'ge-espacio' },
{ t: 'Teorema de Bolzano', d: 'Si una función es continua en un intervalo cerrado $[a, b]$ y toma valores de signo contrario en los extremos, se anula en algún punto de dentro. Asegura que una ecuación tiene solución sin decir cuál es, y es la base del método de bisección. Si la función no es continua, el teorema no dice nada.', v: 'bolzano valores intermedios raiz existe signo contrario', i: 'fn-continuidad' },
{ t: 'Derivabilidad', d: 'Que una función tenga derivada en un punto. Exige continuidad, pero no basta: $|x|$ es continua en 0 y no es derivable, porque tiene un pico. En una función a trozos se comprueba primero que los trozos empalmen y después que las derivadas laterales coincidan.', v: 'derivable derivabilidad derivadas laterales pico', i: 'fn-derivabilidad' },
{ t: 'Regla de L\'Hôpital', d: 'Para calcular el límite de un cociente que da $\\frac{0}{0}$ o $\\frac{\\infty}{\\infty}$, se puede calcular el límite del cociente de las derivadas: $\\lim \\frac{f}{g} = \\lim \\frac{f\'}{g\'}$. Solo vale para esas dos indeterminaciones; aplicarla a cualquier cociente da resultados falsos.', v: 'lhopital l hopital hospital regla limite cociente derivadas', i: 'fn-lhopital' },
{ t: 'Función integral', d: 'La función que a cada $x$ le asigna el área acumulada desde un punto fijo: $F(x) = \\int_a^x f(t)\\,dt$. La variable está en el límite superior. Su derivada es la propia $f$, y eso es el teorema fundamental del cálculo.', v: 'funcion integral area acumulada funcion area', i: 'fn-funcion-integral' },
{ t: 'Teorema fundamental del cálculo', d: 'El resultado que une la derivada con la integral: si $F(x) = \\int_a^x f(t)\\,dt$ y $f$ es continua, entonces $F\'(x) = f(x)$. Dicho de otra forma, integrar y derivar son operaciones inversas, y por eso el área bajo una curva se calcula con una primitiva (regla de Barrow).', v: 'teorema fundamental del calculo barrow newton leibniz', i: 'fn-funcion-integral' },
{ t: 'Fracciones simples', d: 'La descomposición de un cociente de polinomios en suma de fracciones con denominadores de primer o segundo grado: $\\frac{1}{x^2 - 1} = \\frac{1/2}{x - 1} - \\frac{1/2}{x + 1}$. Convierte una integral racional difícil en varias inmediatas, y reaparece al resolver recurrencias con funciones generadoras.', v: 'fracciones simples descomposicion integral racional parciales', i: 'fn-integral-racional' },
{ t: 'Composición de funciones', d: 'Aplicar una función al resultado de otra: $(g\\circ f)(x) = g(f(x))$. Se lee de derecha a izquierda, primero $f$ y después $g$, y el orden importa. Es la estructura que deriva la regla de la cadena.', v: 'composicion compuesta g circulo f funciones encadenadas', i: 'fn-concepto' },
{ t: 'Función inversa', d: 'La función que deshace lo que hace otra: si $f(a) = b$, entonces $f^{-1}(b) = a$. Solo existe si $f$ no repite valores, y su gráfica es la simétrica respecto de la recta $y = x$. Ojo: $f^{-1}$ no es $\\frac{1}{f}$.', v: 'funcion inversa reciproca f menos uno', i: 'fn-concepto' },
{ t: 'Raíces n-ésimas de un complejo', d: 'Todo complejo distinto de cero tiene exactamente $n$ raíces $n$-ésimas. Tienen el mismo módulo, la raíz $n$-ésima del módulo original, y argumentos separados $\\frac{360^\\circ}{n}$: son los vértices de un polígono regular centrado en el origen.', v: 'raices enesimas complejo de moivre poligono regular', i: 'al-complejos' },
{ t: 'Proyección de un vector', d: 'La sombra de un vector sobre la dirección de otro cuando la luz cae en perpendicular. Su longitud con signo es $\\frac{\\vec u\\cdot\\vec v}{|\\vec v|}$. Es la idea que hay detrás de las distancias en el espacio, del reflejo en un espejo y del método de mínimos cuadrados.', v: 'proyeccion proyeccion ortogonal sombra componente', i: 'ge-vectores' },
{ t: 'Cuartiles', d: 'Los tres valores que parten los datos ordenados en cuatro partes iguales: por debajo del primero queda el 25 %, del segundo (la mediana) el 50 % y del tercero el 75 %. La distancia entre el primero y el tercero, el rango intercuartílico, mide la dispersión sin dejarse arrastrar por los datos extremos.', v: 'cuartiles percentiles rango intercuartilico q1 q3', i: 'pe-descriptiva' },
{ t: 'Diagrama de caja', d: 'Un gráfico que resume unos datos con cinco números: una caja del primer al tercer cuartil con una raya en la mediana, bigotes hasta los datos más extremos que no son atípicos, y los atípicos marcados aparte. Permite comparar varios grupos de un vistazo.', v: 'diagrama de caja bigotes boxplot atipicos', i: 'pe-descriptiva' },
{ t: 'Tabla de contingencia', d: 'Una tabla de doble entrada que cuenta cuántos casos hay de cada combinación de dos características, con los totales en los márgenes. Las probabilidades condicionadas se leen dividiendo una casilla entre el total de la fila o columna de lo que se sabe.', v: 'tabla de contingencia doble entrada frecuencias cruzadas', i: 'pe-condicionada' },
{ t: 'Proporción muestral', d: 'La fracción de individuos de una muestra que cumplen algo, $\\hat p$. Sirve para estimar la proporción de toda la población, con un error que se mide con su desviación típica, $\\sqrt{p(1 - p)/n}$: cuatro veces más muestra reduce el error a la mitad.', v: 'proporcion muestral p gorro estimacion encuesta', i: 'pe-proporcion' },
{ t: 'Nivel de significación', d: 'La probabilidad de rechazar una hipótesis que en realidad es cierta que se está dispuesto a aceptar al hacer un contraste, normalmente el 5 % o el 1 %. Fija el valor crítico. Rechazar con un nivel del 5 % no significa que la hipótesis sea falsa con probabilidad del 95 %.', v: 'nivel de significacion alfa error tipo i valor critico', i: 'pe-contraste' },
{ t: 'Heurística', d: 'Una estrategia que ayuda a encontrar la solución de un problema sin garantizarla: empezar por casos pequeños, dibujar, trabajar hacia atrás, buscar un problema parecido. Las recogió George Pólya en 1945. En informática, también se llama así a un método que da soluciones buenas rápidamente cuando la óptima es demasiado cara.', v: 'heuristica polya estrategia resolver problemas', i: 'lg-problemas' },
{ t: 'Algoritmo', d: 'Una receta precisa y finita de pasos que resuelve un tipo de problema: el de Euclides para el máximo común divisor, el de Gauss para los sistemas. Tiene que ser tan exacta que la pueda seguir una máquina sin entender nada, y de ahí sale toda la informática.', v: 'algoritmo receta pasos programa', i: 'lg-algoritmos' },

/* ---------------- más allá del Bachillerato ---------------- */
{ t: 'Componente principal', d: 'Cada una de las direcciones en las que una nube de datos más se estira. Se obtienen como autovectores de la matriz de covarianza: la primera es la que recoge más variabilidad, la segunda la que más recoge entre las perpendiculares a ella, y así sucesivamente. Su autovalor no se parece a la varianza en esa dirección: <strong>es</strong> la varianza, y por eso quedarse con unas pocas pierde exactamente la suma de los autovalores descartados.', v: 'componente principal componentes principales pca reduccion dimension', i: 'av-pca' },
{ t: 'Mínimos cuadrados', d: 'El método para ajustar un modelo a datos que no encajan exactamente: se eligen los parámetros que hacen mínima la suma de los cuadrados de los errores. Geométricamente es proyectar el vector de datos sobre el espacio de lo que el modelo puede producir.', v: 'minimos cuadrados ajuste regresion proyeccion', i: 'av-minimos-cuadrados' },
{ t: 'Ecuaciones normales', d: 'El sistema $A^tA\\,\\hat x = A^t\\vec b$ que da la solución de mínimos cuadrados. Expresa que el residuo es perpendicular a todas las columnas de $A$.', v: 'ecuaciones normales at a minimos cuadrados', i: 'av-minimos-cuadrados' },
{ t: 'Valores singulares', d: 'Los números que miden cuánto estira una matriz en sus direcciones principales: las longitudes de los semiejes de la elipse en la que convierte la circunferencia unidad. Existen para cualquier matriz, son las raíces de los autovalores de $A^tA$, y quedarse con los mayores es la mejor manera de comprimir una matriz.', v: 'valores singulares svd descomposicion compresion', i: 'av-svd' },
{ t: 'Método de Euler', d: 'El método numérico más sencillo para resolver una ecuación diferencial: avanzar a pasos pequeños siguiendo la pendiente que marca la ecuación, $y_{n+1} = y_n + h\\,f(t_n, y_n)$. Su error es proporcional al paso.', v: 'metodo de euler numerico paso edo', i: 'av-edo-numerico' },
{ t: 'Runge-Kutta', d: 'Una familia de métodos numéricos para ecuaciones diferenciales que miran la pendiente en varios puntos de cada paso y la promedian. El de orden 4 usa cuatro pendientes y su error es proporcional a la cuarta potencia del paso: el caballo de batalla del cálculo científico.', v: 'runge kutta rk4 metodo numerico', i: 'av-edo-numerico' },
{ t: 'Resonancia', d: 'El aumento enorme de la amplitud de una oscilación cuando se empuja un sistema justo a su frecuencia natural. Cuanto menor es el rozamiento, mayor el efecto. Es lo que aprovecha una radio para sintonizar una emisora, y lo que tienen que evitar los puentes.', v: 'resonancia frecuencia natural oscilacion forzada', i: 'av-oscilador' },
{ t: 'Amortiguamiento crítico', d: 'El amortiguamiento justo con el que un sistema que oscila vuelve al reposo lo más rápido posible sin llegar a pasarse. Con menos, oscila; con más, vuelve despacio. Para un muelle vale $c = 2\\sqrt{mk}$, y es el objetivo al diseñar una suspensión.', v: 'amortiguamiento critico subamortiguado sobreamortiguado', i: 'av-oscilador' },
{ t: 'Integral doble', d: 'La integral de una función de dos variables sobre una región del plano, $\\iint_R f\\,dA$: el volumen bajo una superficie. Se calcula como dos integrales de una variable seguidas.', v: 'integral doble multiple fubini volumen', i: 'av-integrales-multiples' },
{ t: 'Jacobiano', d: 'El factor que aparece al cambiar de variables en una integral múltiple, y que mide cuánto estira el cambio las áreas o los volúmenes. Es el valor absoluto de un determinante de derivadas. En polares vale $r$, y por eso $dA = r\\,dr\\,d\\theta$.', v: 'jacobiano cambio de variables determinante polares', i: 'av-integrales-multiples' },
{ t: 'Multiplicador de Lagrange', d: 'El número $\\lambda$ que aparece al optimizar una función con una restricción: en el óptimo, $\\nabla f = \\lambda\\nabla g$, los gradientes son paralelos. Además mide cuánto mejoraría el óptimo si la restricción se relajara: en economía, un precio sombra.', v: 'multiplicador de lagrange lambda restriccion optimizacion', i: 'av-lagrange' },
{ t: 'Recurrencia lineal', d: 'Una regla que calcula cada término de una sucesión como combinación fija de los anteriores, como Fibonacci. Se resuelve con la ecuación característica, que da la fórmula del término general.', v: 'recurrencia lineal ecuacion caracteristica sucesion recurrente', i: 'av-recurrencias' },
{ t: 'Número de oro', d: 'El número $\\varphi = \\frac{1 + \\sqrt 5}{2} \\approx 1{,}618$, raíz de $x^2 = x + 1$. Es el límite del cociente entre dos términos consecutivos de Fibonacci.', v: 'numero de oro phi razon aurea proporcion divina', i: 'av-recurrencias' },
{ t: 'Notación O', d: 'La manera de describir cómo crece el coste de un algoritmo con el tamaño del problema, quedándose solo con el término que manda: $3n^2 + 5n = O(n^2)$. Permite comparar algoritmos sin depender del ordenador.', v: 'notacion o grande complejidad coste algoritmo', i: 'av-complejidad' },
{ t: 'P y NP', d: 'Dos clases de problemas. <strong>P</strong>: los que se resuelven en tiempo polinómico. <strong>NP</strong>: aquellos cuyas soluciones se comprueban en tiempo polinómico. Si P es igual a NP es la gran pregunta abierta de la informática.', v: 'p np p frente a np complejidad polinomico', i: 'av-complejidad' },
{ t: 'NP-completo', d: 'Un problema de NP al que se pueden traducir todos los demás de NP con un coste polinómico: los más difíciles de la clase. Si uno solo se resolviera eficientemente, se resolverían todos.', v: 'np completo cook karp sat problema dificil', i: 'av-complejidad' },
{ t: 'Diffie-Hellman', d: 'El método con el que dos partes acuerdan una clave secreta comunicándose en público: cada una envía $g$ elevado a su secreto, módulo un primo, y las dos calculan $g^{ab}$. Su seguridad descansa en la dificultad del logaritmo discreto.', v: 'diffie hellman intercambio de claves clave publica', i: 'av-cripto-curvas' },
{ t: 'Logaritmo discreto', d: 'El problema de encontrar el exponente $a$ sabiendo $g^a \\bmod p$. Con primos grandes no se conoce forma eficiente de resolverlo, y sobre esa dificultad se construye buena parte de la criptografía.', v: 'logaritmo discreto exponente modular criptografia', i: 'av-cripto-curvas' },
{ t: 'Curva elíptica', d: 'El conjunto de soluciones de una ecuación como $y^2 = x^3 + ax + b$. Sus puntos se pueden sumar con una recta, y forman un grupo. Con aritmética modular, es la base de la criptografía de clave pública de casi todos los dispositivos actuales.', v: 'curva eliptica suma de puntos ecc criptografia', i: 'av-cripto-curvas' },

/* ---------------- cibernética, más ---------------- */
{ t: 'Diagrama de bloques', d: 'La representación de un sistema como cajas que transforman señales, unidas por flechas y sumadores. Se reduce con reglas algebraicas: en serie las ganancias se multiplican, en paralelo se suman, y un bucle de realimentación negativa da $\\frac{G}{1 + GH}$.', v: 'diagrama de bloques bucle cerrado ganancia lazo', i: 'cib-bloques' },
{ t: 'Sensibilidad', d: 'Cuánto se nota en la salida de un sistema un cambio relativo en una de sus piezas. En un bucle de realimentación negativa se divide por $1 + GH$: por eso la realimentación convierte piezas imprecisas en un sistema preciso.', v: 'sensibilidad robustez realimentacion', i: 'cib-bloques' },
{ t: 'Windup', d: 'El defecto de un controlador con término integral cuando el actuador está saturado: la integral sigue acumulando error, y al recuperarse el sistema lo empuja demasiado y se pasa de largo. Se evita dejando de integrar mientras dura la saturación.', v: 'windup antiwindup saturacion integral', i: 'cib-control' },
{ t: 'Stock y flujo', d: 'Las dos piezas de la dinámica de sistemas. Un <strong>stock</strong> es algo que se acumula, como el agua de una bañera o la población de un país; un <strong>flujo</strong>, lo que entra o sale por unidad de tiempo. El stock es la integral del flujo neto, y por eso tiene inercia.', v: 'stock flujo dinamica de sistemas acumulacion bañera', i: 'cib-dinamica' },
{ t: 'Captura máxima sostenible', d: 'La mayor cantidad que se puede extraer cada año de una población que crece de forma logística sin agotarla: su crecimiento máximo, $\\frac{rK}{4}$, que se da cuando la población está a la mitad de su capacidad.', v: 'captura maxima sostenible logistica pesca', i: 'cib-dinamica' },
{ t: 'Ganancia de Kalman', d: 'La fracción del camino que recorre la estimación desde la predicción hacia la medida: $K = \\frac{\\sigma_p^2}{\\sigma_p^2 + \\sigma_m^2}$. Si la medida es muy fiable, se acerca a 1; si lo es la predicción, a 0.', v: 'ganancia de kalman innovacion fusion estimacion', i: 'cib-kalman' },
{ t: 'Perceptrón', d: 'Una neurona artificial que suma sus entradas multiplicadas por pesos, se dispara si la suma supera un umbral y aprende corrigiendo los pesos cuando se equivoca. Solo aprende lo que se puede separar con una recta: no puede aprender la O exclusiva.', v: 'perceptron neurona artificial rosenblatt mcculloch pitts', i: 'cib-neurona' },
{ t: 'Aprendizaje por refuerzo', d: 'Aprender a actuar a partir de premios y castigos, sin que nadie diga cuál era la acción correcta. Las acciones que llevan a buenos resultados se vuelven más probables. Es cómo aprendía MENACE, la máquina de cajas de cerillas, y cómo aprenden hoy los programas que juegan al go.', v: 'aprendizaje por refuerzo recompensa menace', i: 'cib-refuerzo' },
{ t: 'Explorar o aprovechar', d: 'El dilema de quien aprende por refuerzo: repetir lo que mejor ha ido hasta ahora o probar algo nuevo que podría ser mejor. La estrategia ε-voraz explora con una probabilidad pequeña y aprovecha el resto de las veces.', v: 'explorar aprovechar exploracion explotacion epsilon voraz bandido', i: 'cib-refuerzo' },
{ t: 'Sistema viable', d: 'En el modelo de Stafford Beer, un sistema capaz de mantener su identidad en un entorno cambiante. Necesita cinco funciones: operaciones, coordinación, control del presente, inteligencia del futuro e identidad, y cada una de sus unidades es a su vez un sistema viable.', v: 'sistema viable stafford beer vsm cybersyn', i: 'cib-viable' },
{ t: 'Reacción-difusión', d: 'Un sistema en el que unas sustancias reaccionan entre sí y a la vez se difunden a distinta velocidad. Alan Turing mostró en 1952 que así pueden aparecer solas manchas y rayas regulares, como las de la piel de muchos animales.', v: 'reaccion difusion patrones de turing gray scott morfogenesis', i: 'cib-autoorganizacion' },

/* ---------------- programación gráfica, más ---------------- */
{ t: 'Curva de Bézier', d: 'Una curva definida por unos pocos puntos de control, que se calcula interpolando entre ellos y volviendo a interpolar (algoritmo de De Casteljau). Empieza en el primero, acaba en el último y los de en medio tiran de ella. Con ellas se dibujan todas las tipografías.', v: 'bezier de casteljau curva puntos de control tipografia', i: 'gfx-curvas' },
{ t: 'Mosaico de Truchet', d: 'Un mosaico hecho con una sola baldosa sin la simetría del cuadrado, colocada al azar en una de sus orientaciones en cada celda. Aunque se elija al azar, los dibujos de las baldosas vecinas empalman y forman caminos continuos.', v: 'truchet mosaico baldosa laberinto teselado', i: 'gfx-mosaicos' },
{ t: 'Transformación de Möbius', d: 'Una función de variable compleja de la forma $\\frac{az + b}{cz + d}$. Transforma circunferencias en circunferencias, y las del tipo $\\frac{z - a}{1 - \\overline{a}z}$ son los desplazamientos del plano hiperbólico en el disco de Poincaré.', v: 'mobius moebius transformacion complejo hiperbolico', i: 'gfx-hiperbolico' },
{ t: 'Trazado de rayos', d: 'La técnica de dibujar en 3D lanzando, por cada píxel, un rayo desde el ojo y calculando con qué choca primero. Chocar con una esfera es una ecuación de segundo grado; con un plano, la intersección recta-plano. Es la geometría analítica de Bachillerato puesta a pintar.', v: 'trazado de rayos ray tracing rayo esfera interseccion', i: 'gfx-trazado' },
{ t: 'Base de la cámara', d: 'Los tres vectores perpendiculares —hacia delante, a la derecha y hacia arriba— con los que se construye el rayo de cada píxel para mirar desde cualquier punto. El de delante apunta al objetivo y los otros dos salen de productos vectoriales.', v: 'camara base ortonormal look at producto vectorial', i: 'gfx-camara' },
{ t: 'Shader con memoria', d: 'Un shader que lee en una textura lo que pintó en el fotograma anterior y calcula el siguiente a partir de él. Deja de ser una fórmula para convertirse en una simulación: con él se ejecutan en la tarjeta gráfica autómatas celulares y ecuaciones de difusión.', v: 'buffer shader con memoria ichannel feedback realimentacion fotograma', i: 'gfx-buffers' },
{ t: 'Convolución', d: 'Sustituir cada píxel por la suma de sus vecinos multiplicados por unos pesos fijos, los del <strong>núcleo</strong>. Con pesos iguales que suman 1 es un desenfoque, la media móvil en dos dimensiones; con pesos que suman 0 se borra lo liso y quedan los bordes, porque es una derivada por diferencias. Da nombre a las redes neuronales convolucionales. La misma operación en una dimensión es la media móvil con la que se suaviza una serie.', v: 'convolucion nucleo kernel filtro desenfoque bordes sobel mascara media movil', i: 'av-convolucion' },
{ t: 'Semitono', d: 'Imprimir grises con una trama de puntos de tinta de un solo color, más grandes donde la imagen es más oscura: desde lejos, el ojo promedia tinta y papel. Lo que tiene que ser proporcional a la oscuridad es el área de cada punto, así que el radio crece con la raíz cuadrada.', v: 'semitono trama de puntos halftone periodico impresion reticula', i: 'gfx-filtros' },
{ t: 'Siete segmentos', d: 'La forma de escribir cifras de los relojes digitales y las calculadoras: siete trazos, que se encienden o no. Cada cifra es una elección de trazos, y esa elección cabe en un número de 7 bits, uno por segmento; el 7, por ejemplo, enciende los tres de arriba y la derecha y su código es 7.', v: 'siete segmentos display digito reloj digital marcador', i: 'gfx-texto' },
{ t: 'Fuente de mapa de bits', d: 'Un tipo de letra en el que cada carácter es una rejilla diminuta de píxeles encendidos o apagados. En un shader, una letra de 3 × 5 se guarda como un número de 15 bits, y cada píxel se lee con la parte entera y el resto entre 2. Cabe exacta en un float porque no pasa de $2^{24}$.', v: 'fuente de bits bitmap font pixel letra glifo', i: 'gfx-texto' },
{ t: 'Advección', d: 'El transporte de una cantidad —tinta, calor, la propia velocidad— por un fluido que se mueve. En un shader se calcula mirando hacia atrás: lo que habrá en un punto dentro de un instante es lo que hay ahora un poco más atrás a lo largo de la velocidad, $c(\\vec x - \\vec v\\,\\Delta t)$. Así es estable con cualquier paso, a costa de difuminar un poco.', v: 'adveccion transporte semilagrangiano fluidos estables stam', i: 'gfx-fluidos' },
{ t: 'Ruido rizado', d: 'Un campo de velocidades hecho con el rotacional de un ruido: si $\\psi$ es cualquier función del plano, $\\vec v = (\\partial\\psi/\\partial y,\\ -\\partial\\psi/\\partial x)$ tiene divergencia cero, así que mueve las cosas sin crear huecos ni amontonarlas, como un líquido. Las curvas de nivel de $\\psi$ son las líneas de corriente.', v: 'ruido rizado curl noise funcion de corriente divergencia cero incompresible', i: 'gfx-fluidos' },
{ t: 'Campo de alturas', d: 'Una superficie descrita por una función de dos variables, $y = h(x, z)$: una altura para cada punto del suelo. Su normal es $(-h_x,\\ 1,\\ -h_z)$ normalizada. La altura sobre el suelo, $p_y - h$, no es una distancia; si la pendiente no pasa de $L$, avanzar $1/\\sqrt{1 + L^2}$ de ella es seguro.', v: 'campo de alturas mapa de alturas heightfield heightmap terreno relieve modelo digital de elevacion', i: 'gfx-terreno' },
{ t: 'Textura sólida', d: 'Una textura que decide el color con las tres coordenadas del punto, $f(x, y, z)$, en vez de pegar una imagen sobre la superficie. Es como tallar el objeto en un bloque de material: no deja costuras ni estiramientos, y un corte enseña la veta que sigue por dentro.', v: 'textura solida textura procedimental 3d marmol madera volumetrica', i: 'gfx-materiales' },
{ t: 'Interpolación trilineal', d: 'Estimar un valor dentro de un cubo a partir de sus ocho esquinas: se interpola a lo largo de $x$ en las cuatro aristas, luego a lo largo de $y$ en las dos caras y por último a lo largo de $z$. Siete mezclas en total. La usan el ruido de valor en 3D y los visores de escáneres médicos entre vóxeles.', v: 'interpolacion trilineal ocho esquinas cubo voxel', i: 'gfx-materiales' },
{ t: 'Transmitancia', d: 'La fracción de luz que atraviesa un medio: 1 si es transparente, 0 si es opaco. Con densidad $\\rho$ y absorción $\\sigma$ vale $T = e^{-\\sigma\\int\\rho\\,ds}$ (ley de Beer-Lambert); al exponente se le llama espesor óptico. Las transmitancias de capas sucesivas se multiplican y sus espesores ópticos se suman.', v: 'transmitancia espesor optico profundidad optica beer lambert bouguer absorcion volumen nubes humo', i: 'gfx-nubes' },

/* ---------------- inteligencia artificial: aprender de los datos ---------------- */
{ t: 'Aprendizaje supervisado', d: 'Aprender una regla a partir de ejemplos ya resueltos: pares de entrada y respuesta correcta. El método ajusta sus parámetros para que sus respuestas se parezcan a las dadas, y lo que se espera de él es que acierte con ejemplos que no ha visto. Se distingue del no supervisado, donde no hay respuestas, y del refuerzo, donde sólo llega un premio.', v: 'aprendizaje supervisado etiquetas ejemplos entrenamiento', i: 'ia-que-es' },
{ t: 'Poda alfa-beta', d: 'La mejora que hace viable la búsqueda en juegos: si una rama ya ha demostrado ser peor que otra que se puede garantizar, no hace falta seguir mirándola. No cambia el resultado —da exactamente la misma jugada que explorar el árbol entero— sino sólo el trabajo, que puede bajar de $b^p$ a la raíz cuadrada de esa cifra con buen orden de jugadas.', v: 'poda alfa beta minimax busqueda juegos arbol', i: 'ia-buscar' },
{ t: 'k vecinos más próximos', d: 'El clasificador más simple que existe: para decidir sobre un caso nuevo, se miran los $k$ ejemplos conocidos más cercanos y se vota. No tiene entrenamiento propiamente dicho —se limita a guardar los datos— y todo su comportamiento depende de qué se considere «cerca», es decir, de la distancia elegida y de la escala de cada variable.', v: 'k vecinos knn proximos distancia votacion', i: 'ia-distancia' },
{ t: 'Árbol de decisión', d: 'Un clasificador hecho de preguntas encadenadas, cada una sobre una sola variable, hasta llegar a una hoja que da la respuesta. Su virtud es que se puede leer y discutir; su defecto, que un árbol profundo memoriza el conjunto de entrenamiento. Se elige cada pregunta por cuánto reduce la mezcla de clases que queda debajo.', v: 'arbol de decision particion impureza gini hoja rama', i: 'ia-arboles' },
{ t: 'Bosque aleatorio', d: 'Muchos árboles entrenados cada uno con una muestra distinta de los datos y de las variables, que votan. Funciona porque sus errores están poco correlacionados: donde uno se equivoca, los demás suelen acertar, y el voto los compensa. Se gana precisión y se pierde justo lo que hacía atractivo a un árbol suelto, que era poder leerlo.', v: 'bosque aleatorio random forest votacion arboles conjunto', i: 'ia-arboles' },
{ t: 'Clasificador ingenuo de Bayes', d: 'Aplicar el teorema de Bayes suponiendo que las variables son independientes dentro de cada clase. La suposición es casi siempre falsa —de ahí lo de ingenuo— y aun así funciona sorprendentemente bien, porque para <em>ordenar</em> las clases no hace falta que las probabilidades sean exactas, sólo que la mayor siga siendo la mayor.', v: 'bayes ingenuo naive independencia clasificador spam', i: 'ia-bayes' },
{ t: 'Suavizado de Laplace', d: 'Sumar uno a todos los recuentos antes de dividir, para que ninguna probabilidad salga exactamente cero. Hace falta porque un único suceso nunca visto pondría a cero todo un producto de probabilidades y decidiría él solo la clasificación, por mucha evidencia que hubiera en contra.', v: 'suavizado laplace add-one recuentos cero probabilidad', i: 'ia-bayes' },
{ t: 'Margen máximo', d: 'El criterio de elegir, entre todas las fronteras que separan bien dos grupos, la que deja el mayor hueco a cada lado. Convierte la clasificación en un problema de optimización con una única solución, y hace que la frontera dependa sólo de los puntos más cercanos a ella, que son los que dan nombre a las máquinas de vectores soporte.', v: 'margen maximo svm vectores soporte frontera separacion', i: 'ia-margen' },
{ t: 'Truco del núcleo', d: 'Trabajar en un espacio de muchas más dimensiones sin llegar a construirlo: basta con saber calcular el producto escalar allí, que es lo único que el método necesita. Permite separar con una recta cosas que en el espacio original no lo son, y es la razón de que un método lineal pueda producir fronteras curvas.', v: 'truco del nucleo kernel trick producto escalar dimensiones', i: 'ia-margen' },
{ t: 'Sigmoide', d: 'La función $\\sigma(z) = 1/(1+e^{-z})$, que aplasta cualquier número real dentro del intervalo $(0,1)$ y permite leer una salida como probabilidad. Su derivada vale $\\sigma(1-\\sigma)$, que no pasa de $0{,}25$: por eso, encadenada muchas veces, apaga el gradiente, y por eso en las capas ocultas se prefiere ReLU.', v: 'sigmoide logistica probabilidad aplastar derivada', i: 'ia-sigmoide' },
{ t: 'Función de pérdida', d: 'La fórmula que convierte «lo bien o mal que va el modelo» en un único número que se puede derivar. Elegirla no es un detalle: decide qué se considera un error grave. El error cuadrático castiga mucho las desviaciones grandes; la entropía cruzada castiga la seguridad equivocada, y es la que se usa al clasificar.', v: 'perdida loss coste objetivo minimizar', i: 'ia-perdida' },
{ t: 'Adam', d: 'El optimizador que se usa por defecto hoy. Combina dos ideas: una media móvil del gradiente, que da inercia, y otra de su cuadrado, que sirve para dividir y dar a cada parámetro su propio ritmo. Así avanza deprisa por las direcciones planas y con cuidado por las empinadas, sin tener que ajustar un ritmo distinto para cada peso.', v: 'adam optimizador momento rmsprop ritmo adaptativo', i: 'ia-perdida' },
{ t: 'Capa oculta', d: 'Cada capa de una red que no es ni la entrada ni la salida. «Oculta» sólo quiere decir que sus valores no se observan desde fuera. Es donde vive la representación intermedia que la red construye, y apilar varias es lo que permite componer transformaciones: cada capa dobla el espacio sobre el resultado de la anterior.', v: 'capa oculta hidden layer profundidad representacion', i: 'ia-red' },
{ t: 'Retropropagación', d: 'El procedimiento que obtiene la derivada de la pérdida respecto de cada parámetro recorriendo hacia atrás las operaciones que se acaban de hacer, aplicando la regla de la cadena en cada una. No es un algoritmo de aprendizaje: es la manera eficiente de calcular todas las derivadas de una vez, y lo que aprende es el optimizador que viene después.', v: 'retropropagacion backpropagation derivadas cadena grafo', i: 'ia-retropropagacion' },
{ t: 'Gradiente que se apaga', d: 'El problema de que, al atravesar muchas capas, el gradiente se multiplica por factores menores que uno y llega a las primeras convertido en casi nada, de modo que esas capas apenas se entrenan. Es la razón de que se sustituyera la sigmoide por ReLU en las capas ocultas y de que se añadieran conexiones residuales.', v: 'gradiente que se apaga desvanece vanishing profundidad relu residual', i: 'ia-retropropagacion' },
{ t: 'Sobreajuste', d: 'Aprenderse los ejemplos concretos en vez de la regla que los explica, de modo que el acierto sobre los datos de entrenamiento es excelente y sobre datos nuevos es malo. Aparece en cuanto hay más parámetros que información en los datos, y se detecta reservando una parte que el modelo no vea durante el entrenamiento.', v: 'sobreajuste overfitting memorizar generalizar validacion', i: 'ia-generalizar' },
{ t: 'Regularización', d: 'Cualquier cosa que se añade para que un modelo no se ajuste demasiado a sus datos: penalizar los pesos grandes, apagar neuronas al azar, parar antes de tiempo. Todas responden a la misma idea: restringir las soluciones posibles para que, entre las que explican los datos, se prefiera la más simple.', v: 'regularizacion penalizacion pesos dropout parada temprana', i: 'ia-generalizar' },
{ t: 'Precisión y exhaustividad', d: 'Las dos preguntas que una tasa de aciertos global esconde. La <strong>precisión</strong> es qué proporción de lo señalado era correcto; la <strong>exhaustividad</strong>, qué proporción de lo que había se llegó a señalar. Se pueden mover una a costa de la otra bajando o subiendo el umbral, y por eso dar sólo una de las dos no dice nada.', v: 'precision exhaustividad recall cobertura umbral f1', i: 'ia-evaluar' },
{ t: 'Matriz de confusión', d: 'La tabla que cuenta los cuatro casos posibles de una clasificación binaria: aciertos de cada clase y los dos tipos de error. Sirve para ver lo que una media esconde, sobre todo cuando las clases están desequilibradas: con un 1 % de casos positivos, contestar siempre que no acierta el 99 % y no encuentra ni uno.', v: 'matriz de confusion falsos positivos negativos desequilibrio', i: 'ia-evaluar' },

/* ---------------- inteligencia artificial: las arquitecturas ---------------- */
{ t: 'Red generativa antagónica', d: 'Dos redes entrenadas una contra otra en un juego de suma cero: el <strong>generador</strong> deforma ruido hasta fabricar datos, y el <strong>discriminador</strong> intenta distinguirlos de los reales. Su interés está en que sustituye la fórmula que mide el parecido por una red que aprende a juzgar, lo cual evita tener que decir a mano en qué se parecen dos imágenes.', v: 'gan red generativa antagonica adversaria generative adversarial network generador discriminador', i: 'ia-gan' },
{ t: 'Generador', d: 'La red que fabrica datos a partir de ruido. No copia nada ni ve jamás los datos de entrenamiento: es una función determinista, y toda la variedad de lo que produce entra por el vector de números al azar que recibe. Visto de otro modo, es un cambio de variable que deforma una distribución uniforme hasta parecerse a la de los datos.', v: 'generador generator ruido latente cambio de variable', i: 'ia-gan' },
{ t: 'Discriminador', d: 'La red que, en una red generativa antagónica, recibe un dato y estima la probabilidad de que sea real y no fabricado. Con el generador congelado, el mejor discriminador posible se puede calcular sin entrenar nada: vale $p(x)/(p(x)+q(x))$, y por tanto contesta $0{,}5$ allí donde los datos reales y los falsos son igual de frecuentes.', v: 'discriminador discriminator juez critico', i: 'ia-gan' },
{ t: 'Colapso de modas', d: 'El fracaso característico de las redes generativas antagónicas: el generador se queda produciendo casi siempre lo mismo en vez de cubrir toda la distribución. No es un error de programación sino una propiedad del objetivo, porque al generador le basta con encontrar <em>un</em> sitio donde el discriminador se equivoque; cubrirlo todo es lo que saldría si el juego llegase a su equilibrio, y casi nunca llega.', v: 'colapso de modas mode collapse modas colapsar generativa', i: 'ia-gan' },
{ t: 'Divergencia de Jensen-Shannon', d: 'Una forma simétrica de medir cuánto se diferencian dos distribuciones: se toma la mezcla $m = (p+q)/2$ y se promedian las dos divergencias de Kullback-Leibler contra ella. Vale 0 cuando las distribuciones coinciden y como mucho $\\log 2$ cuando no comparten nada. Importa porque es exactamente lo que minimiza una red generativa antagónica cuando su discriminador es óptimo.', v: 'jensen shannon divergencia js simetrica mezcla kl', i: 'ia-gan' },
{ t: 'Modelo de difusión', d: 'Un generador que aprende a deshacer, paso a paso, un proceso conocido de destrucción: primero se añade ruido normal a un dato hasta que no queda nada, y luego se entrena una red para quitar un poco de ruido cada vez. Es hoy la base de casi toda la generación de imágenes, y se entrena sin adversario, lo que lo hace mucho más estable que una red generativa antagónica.', v: 'difusion diffusion ddpm denoising quitar ruido generativo', i: 'ia-difusion' },
{ t: 'Score', d: 'El gradiente del logaritmo de una densidad, $\\nabla_x \\log p(x)$: en cada punto, la dirección en la que habría que moverse para que el dato fuera más plausible. Para una normal vale $-(x-\\mu)/\\sigma^2$, o sea que apunta siempre hacia la media. Los modelos de difusión aprenden justamente esto, y por eso se los llama también modelos basados en score.', v: 'score gradiente del logaritmo densidad puntuacion score matching', i: 'ia-difusion' },
{ t: 'Calendario de ruido', d: 'La sucesión de valores $\\beta_t$ que decide cuánto ruido se añade en cada paso del camino de ida de un modelo de difusión. Importa más de lo que parece: si los pasos son demasiado grandes, deshacer uno es tan difícil como generar de cero, y si son demasiado pequeños hacen falta muchísimos. El producto acumulado $\\overline{\\alpha}_t$ dice qué fracción del dato original sobrevive.', v: 'calendario de ruido noise schedule beta alfa barra', i: 'ia-difusion' },
{ t: 'Adversario', d: 'Palabra con dos sentidos distintos en este curso, y conviene no mezclarlos. En criptografía es <em>quien intenta romper el secreto</em>, y todo el diseño se hace suponiendo lo peor sobre él. En aprendizaje automático, «antagónico» o «adversario» describe un entrenamiento en el que dos redes compiten, o un ejemplo construido a propósito para engañar a un modelo. El primero es un enemigo; el segundo, un método.', v: 'adversario antagonico adversarial atacante enemigo', i: 'ia-gan' },

{ t: 'Token', d: 'Cada uno de los trozos en que se parte un texto antes de dárselo a un modelo. No son ni letras ni palabras, sino <strong>trozos de palabra</strong>: las frecuentes suelen ser un solo token y las raras se escriben juntando varios. Es la unidad en la que los modelos cuentan, y también en la que se factura su uso.', v: 'token tokens trozo subpalabra tokenizacion tokenizador', i: 'ia-tokens' },
{ t: 'BPE', d: 'Codificación por pares de bytes: el algoritmo que decide los tokens. Parte de las letras sueltas y repite una operación muy simple —buscar el par de símbolos vecinos más frecuente y sustituirlo por un símbolo nuevo— hasta llegar al tamaño de vocabulario que se quiera. Philip Gage lo publicó en 1994 como método de compresión, sin relación alguna con el lenguaje.', v: 'bpe byte pair encoding codificacion por pares de bytes fusiones gage', i: 'ia-tokens' },
{ t: 'Fuera de vocabulario', d: 'El problema de los sistemas que trabajaban con palabras enteras: tarde o temprano aparece una que no estaba en la lista —un nombre propio, una errata, un término nuevo— y el modelo no tiene forma de representarla. Los trozos de palabra lo eliminan, porque las letras sueltas siguen en el vocabulario y por tanto cualquier cadena se puede escribir.', v: 'fuera de vocabulario oov out of vocabulary palabra desconocida unk', i: 'ia-tokens' },

{ t: 'Perplejidad', d: 'La forma habitual de puntuar un modelo de lenguaje: la entropía cruzada sobre un texto no visto, exponenciada, $2^H$. Se lee como <em>entre cuántas opciones duda el modelo de media</em>, así que vale 1 cuando acierta con total seguridad y el tamaño del vocabulario cuando reparte por igual. Sólo dice algo si el texto es de verdad nuevo, y no se puede comparar entre tokenizadores distintos.', v: 'perplejidad perplexity entropia cruzada evaluar modelo de lenguaje', i: 'ia-secuencias' },
{ t: 'Temperatura', d: 'El número por el que se dividen los logits antes del softmax, $P_i \\propto e^{z_i/\\tau}$. Por debajo de 1 agranda las diferencias y el modelo se vuelve previsible y repetitivo; por encima las aplana y se vuelve disparatado. No añade creatividad: sólo hace más probables las opciones que el modelo puntuaba peor.', v: 'temperatura tau softmax logits muestreo creatividad', i: 'ia-secuencias' },
{ t: 'n-grama', d: 'Un modelo que estima la probabilidad del siguiente símbolo contando qué siguió a cada contexto de $n$ símbolos en un texto. Es una cadena de Markov cuyo estado son los últimos $n$ símbolos. Sus parámetros crecen como $V^{n+1}$, de modo que con poco contexto ya hay muchísimos más parámetros que datos: de ahí que la perplejidad sobre texto nuevo empeore al alargarlo.', v: 'ngrama n-grama bigrama trigrama contexto contar markov', i: 'ia-secuencias' },

{ t: 'Similitud coseno', d: 'El coseno del ángulo entre dos vectores, $\\frac{\\vec u\\cdot\\vec v}{\\Vert\\vec u\\Vert\\,\\Vert\\vec v\\Vert}$, usado para medir cuánto se parecen dos palabras o dos documentos. Se prefiere a la distancia porque no depende del tamaño de los vectores: una palabra diez veces más frecuente que otra no sale lejos sólo por eso, ya que multiplicar por un número positivo no cambia la dirección.', v: 'similitud coseno cosine similarity angulo vectores parecido', i: 'ia-vectores-palabras' },
{ t: 'IDF', d: 'Frecuencia inversa de documento, $\\log(N/n_t)$: el peso que Karen Spärck Jones propuso en 1972 para que las palabras repartidas por todas partes cuenten menos al buscar. Vale cero para un término que aparece en todos los documentos y crece para los que salen en pocos. Es la versión con fórmula de la idea de que lo muy frecuente no distingue nada.', v: 'idf tf-idf frecuencia inversa documento sparck jones recuperacion buscador', i: 'ia-vectores-palabras' },
{ t: 'Hipótesis distribucional', d: 'La idea de que dos palabras significan algo parecido si aparecen rodeadas de las mismas palabras, de modo que se puede representar cada una por el recuento de sus vecinas. Funciona sorprendentemente bien y tiene un límite conocido: mide compañía, no significado, así que los antónimos —que comparten casi todos sus contextos— salen muy próximos entre sí.', v: 'hipotesis distribucional contexto vecinos firth significado', i: 'ia-vectores-palabras' },

{ t: 'Atención', d: 'El mecanismo que deja que cada posición de una secuencia mire a todas las demás: una <strong>media ponderada de valores</strong> cuyos pesos salen de un softmax de productos escalares entre consultas y claves, $\\text{softmax}(QK^t/\\sqrt{d})V$. Sustituyó a las redes recurrentes porque no tiene cuello de botella y se calcula de una vez con multiplicaciones de matrices, en vez de token a token.', v: 'atencion attention consulta clave valor query key value softmax', i: 'ia-atencion' },
{ t: 'Transformador', d: 'La arquitectura que apila muchas veces un mismo bloque: atención multicabeza, una red densa por posición, conexiones residuales y normalización. No hay ninguna idea nueva por encima de eso; lo que separa un modelo de juguete de uno enorme es cuántas veces se repite el bloque y con cuántos números. Es la base de casi todo lo que hoy trabaja con lenguaje.', v: 'transformador transformer bloque multicabeza residual atencion', i: 'ia-atencion' },
{ t: 'Máscara causal', d: 'El recurso que impide a una posición mirar hacia delante: en la matriz de puntuaciones se pone menos infinito en todo lo que está por encima de la diagonal, de modo que el softmax le da peso cero. Es lo que permite entrenar un modelo a predecir el siguiente token con toda la frase a la vez, sin que haga trampa leyendo la respuesta.', v: 'mascara causal enmascarar autorregresivo triangular futuro', i: 'ia-atencion' },
{ t: 'Codificación posicional', d: 'Lo que se suma a cada token para decirle al modelo en qué lugar de la frase estaba, porque la atención por sí sola es indiferente al orden: barajar la entrada no cambiaría su salida. La versión original usa senos y cosenos de frecuencias distintas, elegidos de modo que la misma separación entre dos posiciones dé el mismo parecido esté donde esté en el texto.', v: 'codificacion posicional positional encoding senos posiciones orden', i: 'ia-atencion' },

{ t: 'Preentrenamiento', d: 'La fase en la que un modelo de lenguaje aprende una sola tarea sobre cantidades enormes de texto: acertar el siguiente token. Su rasgo decisivo es que <strong>la etiqueta es el propio texto</strong>, así que no hace falta que nadie anote nada y sirve cualquier escrito. Después vienen ajustes más pequeños para que además obedezca instrucciones.', v: 'preentrenamiento pretraining autosupervisado siguiente token', i: 'ia-llm' },
{ t: 'Ventana de contexto', d: 'La cantidad de tokens que un modelo puede mirar a la vez; lo que queda fuera no existe para él en ese momento. Ampliarla es caro porque el coste de la atención crece con el <strong>cuadrado</strong> de la longitud: duplicar la ventana cuadruplica el trabajo. Casi todas las técnicas de contexto muy largo consisten en no calcular la matriz de atención entera.', v: 'ventana de contexto context window tokens longitud', i: 'ia-llm' },
{ t: 'Ley de escala', d: 'La observación empírica de que la pérdida de un modelo baja siguiendo aproximadamente una ley de potencias respecto del tamaño, los datos y el cómputo. Se dibuja con los dos ejes logarítmicos porque una potencia $L = cN^{-\\alpha}$ es allí una recta de pendiente $-\\alpha$. Medirlas exige hacer crecer las tres cosas a la vez y ajustar el entrenamiento en cada tamaño: con pocos datos y poco presupuesto no se reproducen.', v: 'ley de escala scaling law potencias log-log exponente', i: 'ia-llm' },

{ t: 'Ecuación de Bellman', d: 'La condición que cumple el valor de un estado: vale el mejor premio inmediato más el valor descontado del estado al que se llega. Como el valor aparece a los dos lados no es una fórmula que se evalúe, sino una ecuación que se resuelve repitiendo. Converge porque la operación es una contracción de factor $\\gamma < 1$, lo que garantiza además que la solución sea única.', v: 'bellman valor programacion dinamica contraccion punto fijo', i: 'ia-refuerzo' },
{ t: 'Factor de descuento', d: 'El número $\\gamma$ entre 0 y 1 que dice cuánto vale un premio que llega un paso más tarde. Fija el horizonte del agente y puede invertir su decisión él solo: con $\\gamma$ pequeño prefiere lo inmediato aunque sea menor. Es el mismo cálculo que un tipo de interés al revés, $\\gamma = 1/(1+i)$, y de ahí que el debate sobre qué descuento aplicar a los daños futuros sea una discusión sobre su valor.', v: 'factor de descuento gamma horizonte impaciencia interes', i: 'ia-refuerzo' },
{ t: 'Q-learning', d: 'El método que aprende, para cada pareja de estado y acción, cuánto vale hacer eso allí, corrigiendo cada estimación con el <strong>error de predicción</strong>: la diferencia entre lo que ahora parece que valía y lo que se creía. Su gracia es que no necesita conocer el mundo —sólo probar y mirar qué pasa— y que converge a la política óptima aunque mientras tanto el agente explore al azar.', v: 'q-learning q learning watkins error de prediccion sin modelo', i: 'ia-refuerzo' },

{ t: 'Ejemplo adversario', d: 'Una entrada modificada a propósito para que un modelo se equivoque, construida dando un paso en la dirección del gradiente de la pérdida <em>respecto de la entrada</em>. Lo decisivo es la dirección y no el tamaño: con el mismo paso, el gradiente daña mucho más que una dirección al azar, y la ventaja crece con la dimensión, de modo que en una imagen basta un cambio imperceptible por píxel. Cuesta una sola pasada hacia atrás.', v: 'ejemplo adversario adversarial example fgsm ataque gradiente entrada', i: 'ia-limites' },
{ t: 'Sesgo algorítmico', d: 'La reproducción, por parte de un modelo, de asociaciones que estaban en los datos con que se entrenó. No es una opinión del modelo ni un error de cálculo: su único criterio es acertar, y usará cualquier variable que prediga bien. Es el problema de la variable de confusión, y por eso borrar la columna sensible no basta si queda otra correlacionada: lo que hay que revisar es el resultado desglosado por grupos.', v: 'sesgo algoritmico bias discriminacion datos confusion grupos', i: 'ia-limites' },

/* ---------------- criptografía ---------------- */
{ t: 'Cifrar, codificar y esconder', d: 'Tres cosas que se confunden y conviene separar. <strong>Codificar</strong> es cambiar la forma del mensaje con una tabla que todo el mundo conoce —el morse, el ASCII— y no protege nada. <strong>Esconder</strong> es que no se note que hay mensaje, como la tinta invisible; es la esteganografía, y falla en cuanto alguien mira bien. <strong>Cifrar</strong> es transformarlo de modo que ni teniéndolo entero se pueda leer sin la clave.', v: 'cifrar codificar esconder esteganografia criptografia clave', i: 'cr-secretos' },
{ t: 'Principio de Kerckhoffs', d: 'El criterio de que un sistema debe seguir siendo seguro aunque el enemigo conozca todo su funcionamiento y solo ignore la clave. Parece una exigencia excesiva y es puro sentido práctico: un algoritmo acaba filtrándose o siendo analizado, mientras que una clave se cambia en un segundo. Lo contrario, confiar en que nadie averigüe el método, se llama seguridad por oscuridad y no ha aguantado nunca.', v: 'kerckhoffs principio secreto en la clave seguridad por oscuridad', i: 'cr-secretos' },
{ t: 'Espacio de claves', d: 'El conjunto de todas las claves posibles de un cifrado y, sobre todo, su tamaño, porque de él depende cuánto tarda en probarlas todas la fuerza bruta: con $|K|$ claves y $v$ por segundo, de media $|K|/(2v)$. Se cuenta con combinatoria. Que sea grande es necesario y no suficiente: la sustitución tiene $26!$ claves y se rompe contando letras.', v: 'espacio de claves fuerza bruta numero de claves tamaño de clave', i: 'cr-secretos' },
{ t: 'Cifrado de César', d: 'Desplazar cada letra un número fijo de posiciones en el alfabeto, que en números es $c = (m + k) \\bmod 26$: la aritmética del reloj aplicada a las letras. Su debilidad no está en el diseño sino en el tamaño, porque con 25 claves posibles se prueban todas a mano y la buena se reconoce porque produce castellano.', v: 'cesar desplazamiento alfabeto rot13 fuerza bruta modulo 26', i: 'cr-cesar' },
{ t: 'Sustitución monoalfabética', d: 'El cifrado que cambia cada letra por otra siguiendo una tabla fija, la misma de principio a fin. Tiene $26!$ claves, unas $4 \\cdot 10^{26}$, y durante siglos se creyó irrompible; cae porque cambiar qué letra se escribe no cambia cuántas veces se escribe.', v: 'sustitucion monoalfabetica cifrado de sustitucion alfabeto desordenado', i: 'cr-frecuencias' },
{ t: 'Análisis de frecuencias', d: 'Romper un cifrado contando cuántas veces aparece cada letra y comparándolo con lo normal del idioma. Lo describió al-Kindi en el siglo IX y es el primer criptoanálisis de la historia. En castellano mandan E, A, O, S, N y R, mientras que K y W casi no existen; el parecido se mide con $\\chi^2 = \\sum (O - E)^2 / E$, que compara un texto con el idioma sin necesidad de entenderlo.', v: 'analisis de frecuencias frecuencias letras al kindi criptoanalisis chi cuadrado', i: 'cr-frecuencias' },
{ t: 'Cifrado afín', d: 'Multiplicar y sumar módulo 26: $y = (ax + b) \\bmod 26$, que con $a = 1$ es el César. Solo se puede descifrar si $\\operatorname{mcd}(a, 26) = 1$, porque hace falta el inverso de $a$; eso deja doce valores válidos de $a$ y 312 claves, y dos letras conocidas lo rompen.', v: 'afin cifrado afin multiplicar y sumar 312 claves', i: 'cr-afin' },
{ t: 'Inverso modular', d: 'El número que multiplicado por otro da 1 en la aritmética del reloj: $a\\,a^{-1} \\equiv 1 \\pmod n$. Existe solo si $\\operatorname{mcd}(a, n) = 1$ y se calcula con Euclides extendido. Es lo que sustituye a la división, porque dividir módulo $n$ es multiplicar por el inverso, y sin él no se puede deshacer ningún cifrado que multiplique.', v: 'inverso modular inverso multiplicativo dividir modulo euclides', i: 'cr-afin' },
{ t: 'Cifrado de Vigenère', d: 'Varios Césares que se turnan: se escribe una palabra clave repetida debajo del mensaje y cada letra se desplaza según la suya, $c_i = (m_i + k_{i \\bmod L}) \\bmod 26$. Confundió a Europa tres siglos porque aplana las frecuencias del texto entero, y cae en cuanto se averigua la longitud de la clave, porque entonces cada columna vuelve a ser un César.', v: 'vigenere polialfabetico palabra clave columnas', i: 'cr-vigenere' },
{ t: 'Índice de coincidencia', d: 'La probabilidad de que dos letras tomadas al azar de un texto sean la misma: $\\sum n(n-1) / (N(N-1))$. Vale unos $0{,}075$ en castellano y unos $0{,}038$ si las letras salen al azar, así que detecta si un texto conserva la estructura de un idioma sin entenderlo. Probando longitudes de clave, la buena es la que devuelve el índice alto.', v: 'indice de coincidencia ic friedman periodo longitud de clave', i: 'cr-vigenere' },
{ t: 'Método de Kasiski', d: 'La manera de averiguar la longitud de la clave de un Vigenère: se buscan trozos repetidos en el texto cifrado y se miden las distancias entre ellos, porque una repetición suele salir de la misma palabra cifrada con el mismo trozo de clave. El máximo común divisor de esas distancias da la longitud.', v: 'kasiski repeticiones distancias mcd longitud de clave babbage', i: 'cr-vigenere' },
{ t: 'Transposición', d: 'Cifrar cambiando el orden de las letras en vez de cambiar las letras. Lo hacen la escítala espartana y el cifrado por columnas con palabra clave, donde la clave es una permutación. Se reconoce al instante, porque las frecuencias del cifrado son exactamente las del castellano: las letras son las mismas.', v: 'transposicion escitala columnas permutacion desordenar anagrama', i: 'cr-transposicion' },
{ t: 'Cifrado producto', d: 'El que combina una sustitución y una transposición, de modo que ninguno de los dos ataques clásicos lo rompe por separado: las frecuencias ya no delatan y el orden tampoco. De aquí sale la receta de todos los cifrados modernos por bloques.', v: 'cifrado producto sustituir y transponer combinado', i: 'cr-transposicion' },
{ t: 'Cifrado de Hill', d: 'Cifrar bloques de letras multiplicándolos por una matriz módulo 26, $y = Kx \\bmod 26$. Solo se puede descifrar si $\\operatorname{mcd}(\\det K, 26) = 1$, y la inversa se calcula con la adjunta y el inverso modular del determinante. Aporta difusión, porque cada letra cifrada depende de varias del mensaje, pero al ser lineal dos pares conocidos entregan la clave.', v: 'hill matrices modulo 26 bloques determinante difusion', i: 'cr-hill' },
{ t: 'XOR', d: 'La operación bit a bit que da 1 cuando los dos bits son distintos y 0 cuando son iguales; es la suma módulo 2. Lo que la hace útil para cifrar es que se deshace consigo misma, $x \\oplus x = 0$, de modo que cifrar y descifrar son exactamente la misma operación.', v: 'xor o exclusivo suma modulo 2 bits oplus', i: 'cr-vernam' },
{ t: 'Libreta de un solo uso', d: 'Cifrar haciendo XOR del mensaje con una clave aleatoria, tan larga como él y usada una sola vez. Es el único cifrado del que se ha demostrado que es irrompible, y sus tres condiciones son justamente lo que lo hace poco práctico. Reutilizar la clave lo arruina del todo, porque entonces $c_1 \\oplus c_2 = m_1 \\oplus m_2$ y los mensajes se descubren el uno al otro.', v: 'libreta de un solo uso one time pad vernam cuaderno de un solo uso', i: 'cr-vernam' },
{ t: 'Secreto perfecto', d: 'La propiedad de que el texto cifrado no diga absolutamente nada sobre el mensaje: $P(m \\mid c) = P(m)$. Se consigue cuando para cada mensaje posible existe una clave que produce el cifrado interceptado, así que el enemigo no puede descartar ninguno. Shannon demostró que exige una clave al menos tan larga como el mensaje, y por eso el resto de la criptografía se conforma con que romperla cueste demasiado.', v: 'secreto perfecto shannon seguridad incondicional perfecto', i: 'cr-vernam' },
{ t: 'Enigma', d: 'La máquina de cifrar alemana de la Segunda Guerra Mundial: tres rotores que giran, un reflector y un tablero de clavijas. Cada rotor es una permutación, y girarlo la conjuga, $\\sigma^{-i}\\rho\\,\\sigma^{i}$. Su comodidad fue su grieta: el reflector hacía que descifrar fuese teclear el cifrado, pero también que ninguna letra se cifrase como sí misma.', v: 'enigma rotores reflector clavijas rejewski turing bomba', i: 'cr-enigma' },
{ t: 'Entropía de una clave', d: 'La medida de incertidumbre de Shannon aplicada a adivinar un secreto: $H = \\log_2 N$ bits si se elige al azar entre $N$ posibilidades, y entonces la fuerza bruta necesita $2^{H-1}$ intentos de media. Es del proceso que la eligió y no de la cadena: una contraseña larga elegida con un patrón previsible, «ciudad más año», vale los 25 bits del patrón por muchas letras que tenga.', v: 'entropia de clave bits de entropia contraseña adivinar fuerza bruta', i: 'cr-entropia' },
{ t: 'Generador pseudoaleatorio criptográfico', d: 'Un generador de números al azar cuya salida no se puede predecir aunque se hayan visto muchos anteriores. Un generador congruencial lineal corriente no lo es: tres valores consecutivos bastan para deducir la fórmula y adivinar el resto. Las claves salen siempre del generador criptográfico del sistema, alimentado con azar físico; el azar malo es la causa más común de fallo real.', v: 'generador pseudoaleatorio csprng azar semilla congruencial lineal impredecible', i: 'cr-entropia' },
{ t: 'Cifrado de flujo', d: 'El que estira una clave corta en un chorro de bits y lo combina con el mensaje por XOR: es una libreta de un solo uso con la libreta fabricada. Hereda su punto débil, porque si el flujo se repite dos mensajes se descubren, y además no detecta alteraciones: cambiar un bit del cifrado cambia ese bit del mensaje y nada más.', v: 'cifrado de flujo stream cipher chorro de bits rc4 chacha', i: 'cr-flujo' },
{ t: 'Registro de desplazamiento con realimentación lineal (LFSR)', d: 'Un registro de $n$ bits que en cada paso se desplaza y mete por delante el XOR de unas posiciones fijas, las que marca un polinomio. Con un polinomio primitivo recorre $2^n - 1$ estados antes de repetirse y es rapidísimo en circuito; pero es lineal, y $2n$ bits de su salida bastan para reconstruirlo entero, así que nunca se usa solo.', v: 'lfsr registro de desplazamiento realimentacion lineal taps polinomio primitivo berlekamp massey', i: 'cr-flujo' },
{ t: 'Nonce', d: 'Un número que se usa una sola vez. No es secreto y no necesita serlo: su trabajo es que el mismo mensaje con la misma clave no produzca nunca dos veces el mismo cifrado. Repetirlo equivale a reutilizar la libreta de un solo uso, y es uno de los fallos más graves y más frecuentes de la criptografía real.', v: 'nonce numero de un solo uso iv vector inicial repetir nonce', i: 'cr-flujo' },
{ t: 'Cifrado por bloques', d: 'El que cifra trozos de tamaño fijo y que, para cada clave, es una permutación de todos los bloques posibles, calculada con una receta corta en vez de guardada en una tabla imposible. AES es el ejemplo vivo. Por sí solo no cifra un mensaje: hace falta además un modo de operación.', v: 'cifrado por bloques block cipher permutacion bloque aes des', i: 'cr-bloque' },
{ t: 'Confusión y difusión', d: 'Las dos exigencias de Shannon para un cifrado. La <strong>confusión</strong> enreda la relación entre la clave y el cifrado, y la ponen las cajas de sustitución; la <strong>difusión</strong> reparte la influencia de cada bit del mensaje por todo el bloque, y la ponen las permutaciones y las mezclas. Ninguna basta sola, y por eso se alternan a pequeña escala durante muchas rondas.', v: 'confusion difusion shannon red de sustitucion y permutacion rondas', i: 'cr-bloque' },
{ t: 'Efecto avalancha', d: 'La propiedad de que cambiar un solo bit de la entrada cambie alrededor de la mitad de los bits de la salida, y de manera impredecible. Es la comprobación más barata de que un cifrado o una función hash se comportan: si cambia bastante menos de la mitad, hay una grieta por donde empezar a tirar.', v: 'efecto avalancha avalancha un bit cambia la mitad', i: 'cr-bloque' },
{ t: 'Caja de sustitución (S-box)', d: 'La tabla pequeña que cambia unos pocos bits por otros y aporta la no linealidad de un cifrado por bloques, sin la cual todo se reduciría a un sistema de ecuaciones que se despeja. La de AES es el inverso en el cuerpo de 256 elementos seguido de una mezcla lineal: no lineal, pero con fórmula, para que no haya que confiar en una tabla sacada de la nada.', v: 'caja de sustitucion s-box sbox no lineal tabla', i: 'cr-bloque' },
{ t: 'Red de Feistel', d: 'Una estructura de cifrado que parte el bloque en dos mitades y en cada ronda hace $L_{i+1} = R_i$ y $R_{i+1} = L_i \\oplus f(R_i, K_i)$. Su gracia es que se deshace repitiendo las mismas rondas con las claves al revés, sin necesidad de invertir nunca $f$: por eso $f$ puede ser cualquier cosa, y cuanto más no lineal, mejor. Es la estructura de DES.', v: 'feistel des ronda mitades estructura reversible', i: 'cr-feistel' },
{ t: 'Encuentro a medio camino', d: 'El ataque que demuestra que cifrar dos veces con dos claves no duplica la seguridad: en lugar de probar los $2^{2k}$ pares se cifra por un lado, se descifra por el otro y se buscan coincidencias, con $2^{k+1}$ operaciones y una tabla de $2^{k}$. Es la razón de que el triple DES cifre tres veces y no dos.', v: 'encuentro a medio camino meet in the middle doble cifrado triple des', i: 'cr-feistel' },
{ t: 'Cuerpo de 256 elementos', d: 'La aritmética en la que cada byte es un polinomio de grado menor que 8 con coeficientes 0 y 1. Sumar es XOR, sin llevadas; multiplicar es multiplicar polinomios y reducir módulo $x^8 + x^4 + x^3 + x + 1$. Como ese polinomio es irreducible, todo byte distinto de cero tiene inverso y se puede dividir. Es la aritmética de AES, de los códigos QR y de los CD.', v: 'cuerpo finito galois gf 256 byte polinomio irreducible rijndael', i: 'cr-galois' },
{ t: 'AES', d: 'El cifrado por bloques que usa hoy casi todo: dieciséis bytes puestos en una rejilla $4 \\times 4$ y diez rondas de cuatro operaciones —SubBytes, ShiftRows, MixColumns y AddRoundKey—, con la clave expandida en once claves de ronda. Se confía en él porque lleva veinticinco años de ataques públicos y el mejor conocido todavía cuesta $2^{126}$, no porque lo diga ninguna autoridad.', v: 'aes rijndael subbytes shiftrows mixcolumns addroundkey rondas', i: 'cr-aes' },
{ t: 'Modo de operación', d: 'La receta que dice cómo cifrar un mensaje largo con un cifrado que solo sabe cifrar un bloque: cómo se rellena y cómo se encadenan los bloques. Elegirlo mal arruina un cifrado impecable. En <strong>ECB</strong> cada bloque se cifra igual, así que bloques iguales dan cifrados iguales y la silueta de una imagen se ve a través del cifrado; <strong>CBC</strong> encadena con el bloque anterior y <strong>CTR</strong> convierte el cifrado de bloque en uno de flujo.', v: 'modo de operacion ecb cbc ctr encadenar relleno pinguino', i: 'cr-modos' },
{ t: 'Vector de inicialización (IV)', d: 'El bloque de arranque que se le da a un modo encadenado como CBC para que dos mensajes que empiezan igual no produzcan cifrados que empiezan igual. No es secreto, pero tiene que ser nuevo e impredecible en cada mensaje: repetirlo delata que dos mensajes comienzan del mismo modo.', v: 'vector de inicializacion iv cbc bloque inicial', i: 'cr-modos' },
{ t: 'Función hash criptográfica', d: 'Una función que resume cualquier cantidad de datos en una huella de tamaño fijo, sin clave y sin inversa, y que promete tres cosas: que de la huella no se vuelve al dato (preimagen), que no se puede sustituir un documento por otro con la misma huella (segunda preimagen) y que no se pueden fabricar dos cualesquiera que coincidan (colisión). No confundir con el <em>hash</em> de gráficos, al que solo se le pide parecer aleatorio.', v: 'funcion hash criptografica sha256 huella digital resumen preimagen md5 sha1 merkle damgard', i: 'cr-hash' },
{ t: 'Colisión', d: 'Dos entradas distintas con la misma huella. Existen a la fuerza, porque hay muchos más mensajes que huellas; lo que se exige a una función hash es que nadie sea capaz de encontrar una. Cuesta $2^{n/2}$ intentos y no $2^{n}$ por la paradoja del cumpleaños, y de ahí que las huellas de hoy tengan 256 bits. Encontrar colisiones de MD5 lleva segundos, y por eso está rota.', v: 'colision hash resistencia a colisiones md5 sha1 rota', i: 'cr-hash' },
{ t: 'Paradoja del cumpleaños', d: 'El hecho de que en un grupo de 23 personas ya sea más probable que no que dos coincidan de cumpleaños. No es una paradoja sino un recuento: lo que crece deprisa no es el número de personas sino el de parejas. En criptografía fija el coste de encontrar una colisión, $2^{n/2}$ en vez de $2^{n}$, y es también lo que hace funcionar al método rho de factorización.', v: 'paradoja del cumpleaños cumpleaños colision raiz cuadrada parejas', i: 'cr-hash' },
{ t: 'Código de autenticación de mensaje (MAC)', d: 'Una etiqueta calculada a partir del mensaje y de una clave compartida que viaja junto a él, de modo que quien no tenga la clave no puede fabricar ninguna válida. Hace falta porque cifrar no impide alterar: en modo CTR, cambiar un bit del cifrado cambia ese mismo bit del mensaje, y con eso se modifica un importe sin haberlo leído.', v: 'mac codigo de autenticacion etiqueta sello integridad autenticar', i: 'cr-mac' },
{ t: 'HMAC', d: 'La manera correcta de construir un código de autenticación con una función hash, metiendo la clave dos veces: $H((k \\oplus \\text{opad}) \\Vert H((k \\oplus \\text{ipad}) \\Vert m))$. El atajo evidente, $H(k \\Vert m)$, es inseguro por la extensión de longitud, que permite alargar el mensaje y calcular la etiqueta del resultado sin conocer la clave.', v: 'hmac extension de longitud opad ipad clave hash', i: 'cr-mac' },
{ t: 'Cifrado autenticado', d: 'El que cifra y sella en una sola operación, de modo que no se pueda olvidar la mitad ni equivocarse en el orden. AES-GCM y ChaCha20-Poly1305 son los de uso corriente. La regla que encapsulan es cifrar y después sellar, y verificar el sello <em>antes</em> de descifrar, porque cualquier error que dé el descifrador sobre datos no verificados es una fuga.', v: 'cifrado autenticado aead aes gcm chacha20 poly1305 cifrar y sellar', i: 'cr-mac' },
{ t: 'Sal', d: 'Un valor aleatorio y distinto para cada usuario que se añade a la contraseña antes de calcular su hash, y que se guarda en claro al lado. No es secreta: su trabajo es ser distinta. Con ella el atacante tiene que repetir el ataque usuario por usuario y las tablas precalculadas dejan de servir. Lo que no hace es arreglar una contraseña mala.', v: 'sal salt contraseñas hash tablas precalculadas rainbow', i: 'cr-contrasenas' },
{ t: 'Hash lento', d: 'Una función de hash de contraseñas hecha cara a propósito, por iteraciones o por consumo de memoria: PBKDF2, bcrypt, scrypt, Argon2. Al usuario legítimo le cuesta una décima de segundo y a quien prueba millones de candidatos le multiplica el trabajo por ese mismo factor, que se elige. Usar SHA-256 a secas permite diez mil millones de intentos por segundo en una tarjeta gráfica.', v: 'hash lento factor de coste iteraciones pbkdf2 bcrypt scrypt argon2 derivacion de contraseña', i: 'cr-contrasenas' },
{ t: 'Euclides extendido', d: 'La versión del algoritmo de Euclides que, además del máximo común divisor, devuelve los coeficientes de $ax + ny = \\operatorname{mcd}(a, n)$. Cuando ese máximo común divisor es 1, el coeficiente $x$ es el inverso de $a$ módulo $n$. Cuesta como mucho $2\\log_2 n$ divisiones, o sea microsegundos con números de 2048 bits, y es la herramienta que sostiene todo el bloque.', v: 'euclides extendido identidad de bezout inverso modular mcd coeficientes', i: 'cr-modular' },
{ t: 'Exponenciación por cuadrados sucesivos', d: 'La manera de calcular $a^{b} \\bmod n$ con exponentes enormes: se recorre el exponente en binario elevando al cuadrado en cada paso y multiplicando donde hay un 1, reduciendo módulo $n$ siempre. Un exponente de mil bits cuesta unos mil pasos en lugar de $2^{1000}$ multiplicaciones, y sin esto la clave pública sería inviable.', v: 'exponenciacion cuadrados sucesivos potencia modular binario rapida pingala', i: 'cr-modular' },
{ t: 'Teorema chino del resto', d: 'El resultado de que unos restos respecto de módulos primos entre sí determinan un único número módulo el producto de todos, y que además dice cómo recomponerlo. Su consecuencia práctica es que trabajar módulo $pq$ es trabajar módulo $p$ y módulo $q$ por separado: con eso RSA descifra unas cuatro veces más rápido.', v: 'teorema chino del resto crt sunzi restos modulos primos entre si', i: 'cr-modular' },
{ t: 'Test de Miller-Rabin', d: 'La prueba que decide si un número es primo sin factorizarlo: se escribe $n - 1 = 2^{s}d$ y se mira la sucesión $a^{d}, a^{2d}, \\dots$, que en un primo tiene que llegar a 1 pasando por $-1$. Al menos tres cuartas partes de las bases delatan a un compuesto, así que con $k$ bases al azar el error queda por debajo de $4^{-k}$. Es lo que fabrica los primos de RSA.', v: 'miller rabin test de primalidad probabilista testigo bases primo', i: 'cr-primos' },
{ t: 'Número de Carmichael', d: 'Un número compuesto que pasa el test de Fermat con todas las bases posibles, como el 561. Son la razón de que el test de Fermat no baste por muchas bases que se prueben, y de que en su lugar se use Miller-Rabin, que mira además las raíces cuadradas de 1 y no se deja engañar.', v: 'carmichael fermat pseudoprimo 561 test de primalidad', i: 'cr-primos' },
{ t: 'Criptografía de clave pública', d: 'La idea de usar dos claves distintas, una pública para cerrar y otra privada para abrir, de modo que dos desconocidos puedan entenderse sin haber acordado antes ningún secreto. Descansa siempre en un problema fácil de plantear y difícil de deshacer: multiplicar dos primos es inmediato y factorizar el producto no, y lo mismo pasa con el logaritmo discreto.', v: 'clave publica asimetrica clave privada criptografia asimetrica', i: 'cr-rsa' },
{ t: 'RSA', d: 'El cifrado de clave pública construido sobre la dificultad de factorizar: se toman dos primos grandes, $n = pq$, se publica $(n, e)$ con $e$ igual a 65 537 y se guarda $d = e^{-1} \\bmod \\varphi(n)$. Cifrar es $m^{e}$ y descifrar $c^{d}$, y funciona por el teorema de Euler. Hoy el mínimo son 2048 bits, que equivalen a unos 112 bits de clave simétrica.', v: 'rsa rivest shamir adleman clave publica factorizacion exponente 65537', i: 'cr-rsa' },
{ t: 'Relleno (OAEP)', d: 'La aleatoriedad que se le añade al mensaje antes de cifrarlo con RSA. Sin ella el cifrado es determinista —dos veces el mismo mensaje da el mismo cifrado, y con pocas opciones se prueban todas— y además es multiplicativo, lo que permite manipularlo sin abrirlo. Cada detalle del relleno está ahí por un ataque que funcionó contra el RSA de libro.', v: 'relleno padding oaep rsa de libro maleabilidad determinista', i: 'cr-rsa' },
{ t: 'Método de Fermat (factorización)', d: 'Factorizar buscando $n = a^{2} - b^{2}$, probando valores de $a$ desde $\\lceil\\sqrt n\\rceil$ hacia arriba. Encuentra en un instante los productos de dos primos demasiado próximos entre sí, y es la razón de que los dos primos de una clave RSA se generen al azar e independientes en lugar de buscarlos «cerca».', v: 'fermat factorizacion diferencia de cuadrados primos cercanos', i: 'cr-factorizar' },
{ t: 'Pollard rho', d: 'El método de factorización que itera $x^{2} + c$ módulo $n$ y espera una repetición, apoyándose en la paradoja del cumpleaños: encuentra un factor $p$ en unos $\\sqrt p$ pasos. Barre deprisa los factores pequeños y no araña una clave RSA, donde eso sigue siendo $2^{512}$. Contra claves grandes se usan las cribas, que cuestan algo intermedio entre polinomio y exponencial.', v: 'pollard rho factorizacion cumpleaños ciclo criba', i: 'cr-factorizar' },
{ t: 'Generador de un grupo', d: 'Un elemento cuyas potencias sucesivas recorren todo el grupo. Módulo un primo $p$, el orden de cualquier elemento divide a $p - 1$, y con un primo seguro, $p = 2q + 1$, todos menos $\\pm 1$ tienen orden grande, que es lo que interesa. No confundirlo con el <em>generador</em> de una red generativa antagónica, que es una red neuronal y no tiene que ver.', v: 'generador grupo orden primo seguro raiz primitiva', i: 'cr-logdiscreto' },
{ t: 'Paso de bebé, paso de gigante', d: 'El algoritmo que resuelve el logaritmo discreto en unas $2\\sqrt p$ operaciones en lugar de $p$: se guarda una tabla de potencias pequeñas y después se dan saltos grandes buscando coincidencias. Su consecuencia es la regla de oro de los tamaños de clave: la seguridad de un grupo es la raíz cuadrada de su orden, así que 256 bits de grupo dan 128 de seguridad.', v: 'paso de bebe paso de gigante baby step giant step shanks logaritmo discreto', i: 'cr-logdiscreto' },
{ t: 'ElGamal', d: 'El cifrado de clave pública que sale de convertir Diffie-Hellman en cifrado: se envía el par $(g^{k},\\ m\\,y^{k})$, con un $k$ al azar y de un solo uso. Es aleatorio por construcción, así que el mismo mensaje nunca da dos veces el mismo cifrado, y repetir el $k$ lo rompe igual que repetir la libreta.', v: 'elgamal cifrado logaritmo discreto clave publica probabilista', i: 'cr-logdiscreto' },
{ t: 'Ataque del hombre en el medio', d: 'El de quien se coloca en mitad del canal y se hace pasar por cada uno ante el otro, acordando una clave distinta con cada lado y leyendo y reenviando todo. Es la razón de que Diffie-Hellman por sí solo no baste: acuerda una clave con alguien, pero no dice con quién. Se cierra firmando lo que se intercambia y comprobando la firma contra un certificado.', v: 'hombre en el medio man in the middle mallory interceptar suplantar', i: 'cr-logdiscreto' },
{ t: 'Firma digital', d: 'Un dato que solo puede producir quien tiene la clave privada y que cualquiera puede verificar con la pública. Con RSA es $s = H(m)^{d} \\bmod n$, y verificar es comprobar que $s^{e} = H(m)$. A diferencia de un código de autenticación, prueba la autoría ante un tercero, porque el verificador no podría haberla fabricado. Se firma el hash del mensaje y no el mensaje, y una firma válida prueba quién firmó, no que lo firmado sea cierto.', v: 'firma digital firmar verificar autoria no repudio schnorr ecdsa', i: 'cr-firmas' },
{ t: 'Doblar y sumar', d: 'La manera de calcular $kG$ en una curva elíptica sin sumar $G$ consigo mismo $k$ veces: se recorre $k$ en binario doblando el punto en cada paso y sumando donde hay un 1. Con $k$ de 256 bits son unas 384 operaciones, mientras que volver de $kG$ a $k$ cuesta $2^{128}$. En esa asimetría está toda la criptografía de curvas.', v: 'doblar y sumar multiplicacion escalar punto curva eliptica binario', i: 'cr-curvas' },
{ t: 'Teorema de Hasse', d: 'La cota que dice cuántos puntos tiene una curva elíptica módulo $p$: el número está entre $p + 1 - 2\\sqrt p$ y $p + 1 + 2\\sqrt p$, o sea que es aproximadamente $p$. Importa porque la seguridad depende del orden del grupo de puntos, y por eso se eligen curvas en las que ese número es primo.', v: 'hasse numero de puntos curva eliptica orden cota', i: 'cr-curvas' },
{ t: 'Certificado digital', d: 'La firma de una autoridad reconocida sobre la afirmación «este nombre tiene esta clave pública, y hasta esta fecha». Es lo que convierte una clave pública recibida por un canal abierto en la clave de alguien concreto, y lo que hay detrás del candado del navegador. Verificarlo es comprobar cuatro cosas: la firma, la cadena hasta una raíz, el nombre y las fechas.', v: 'certificado x509 candado navegador autoridad tls https', i: 'cr-certificados' },
{ t: 'Cadena de confianza', d: 'La sucesión de certificados que va del de una web hasta una de las raíces que el navegador trae de fábrica, cada uno firmado por el de arriba. Esa lista de raíces es la única confianza que no se demuestra: todo lo demás son firmas. Por eso una raíz comprometida puede firmar lo que quiera, y por eso hay auditorías y registros públicos.', v: 'cadena de confianza raiz autoridad de certificacion ca intermedio diginotar', i: 'cr-certificados' },
{ t: 'Secreto hacia delante', d: 'La propiedad de que robar hoy la clave privada de un servidor no permita descifrar el tráfico de ayer que alguien tuviera grabado. Se consigue acordando cada sesión con un Diffie-Hellman efímero y borrando los secretos al terminar: la clave del certificado solo firma, no cifra nada que haya que guardar.', v: 'secreto hacia delante forward secrecy efimero borrar claves sesion', i: 'cr-certificados' },
{ t: 'Derivación de claves (HKDF)', d: 'El procedimiento que convierte un secreto compartido en las varias claves distintas que hacen falta —una por sentido de la conversación y por finalidad—, mezclándolo con una función hash. La regla que impone es doble: el secreto en bruto no se usa nunca como clave, y la misma clave no se usa para dos cosas.', v: 'derivacion de claves hkdf kdf clave de sesion secreto compartido', i: 'cr-certificados' },
{ t: 'Esquema de Shamir', d: 'La manera de repartir un secreto entre varias personas de modo que hagan falta $k$ cualesquiera para recuperarlo: se esconde el secreto en $f(0)$ de un polinomio de grado $k - 1$ con los demás coeficientes al azar, y se le da a cada uno un punto $(i, f(i))$. Con $k$ puntos se recupera interpolando por Lagrange; con $k - 1$, y trabajando módulo un primo, todos los secretos siguen siendo igual de posibles.', v: 'shamir compartir secreto umbral partes lagrange interpolacion reparto', i: 'cr-compartir' },
{ t: 'Prueba de conocimiento cero', d: 'Un protocolo con el que se convence a alguien de que se sabe un secreto sin revelar nada de él. Lo que la define es un criterio muy concreto: todo lo que el verificador acaba viendo podría haberlo fabricado él solo, así que no ha aprendido nada. El protocolo de Schnorr la hace en tres pasos: compromiso, reto y respuesta.', v: 'conocimiento cero zero knowledge schnorr ali baba reto respuesta simulador', i: 'cr-conocimiento-cero' },
{ t: 'Compromiso', d: 'Un valor que ata a una elección sin enseñarla, como un sobre lacrado: se publica $H(n \\Vert v)$ con un nonce y más tarde se abre enseñando $v$ y $n$. Oculta gracias al nonce y ata gracias a la resistencia a colisiones, y con esas dos propiedades se puede echar una moneda al aire por teléfono.', v: 'compromiso commitment sobre cerrado moneda por telefono ocultar atar', i: 'cr-conocimiento-cero' },
{ t: 'Fiat-Shamir', d: 'El truco de sustituir el reto que el verificador elegía al azar por un hash de lo dicho hasta ese momento, con lo que una conversación de tres pasos se convierte en un solo mensaje que no necesita al verificador. Es lo que convierte una prueba de conocimiento cero en una firma digital.', v: 'fiat shamir reto hash no interactiva firma schnorr', i: 'cr-conocimiento-cero' },
{ t: 'Cadena de bloques', d: 'Una lista de bloques en la que cada uno incluye el hash del anterior, $h_i = H(h_{i-1} \\Vert \\text{datos}_i)$. Alterar algo del pasado rompe todos los hashes siguientes, así que no impide el cambio: lo delata. No necesita moneda ni minería —Git, los registros de certificados y el sellado de tiempo son cadenas de hashes—, porque la prueba de trabajo solo hace falta cuando nadie manda.', v: 'cadena de bloques blockchain hashes encadenados git sellado de tiempo', i: 'cr-cadena' },
{ t: 'Árbol de Merkle', d: 'Un árbol construido hasheando los datos de dos en dos, y luego los resultados de dos en dos, hasta llegar a una sola raíz. Sirve para demostrar que un dato concreto está entre un millón enseñando solo $\\lceil\\log_2 n\\rceil$ hashes —unos veinte— en lugar de todos los datos, y es lo que permite verificar desde un móvil.', v: 'merkle arbol raiz prueba de pertenencia hashes logaritmo', i: 'cr-cadena' },
{ t: 'Prueba de trabajo', d: 'La exigencia de encontrar un nonce que haga que el hash de un bloque empiece por $d$ ceros. Como el hash no se puede invertir, solo queda probar: cuesta $2^{d}$ intentos de media y verificarlo cuesta uno. Cada bit de dificultad duplica el coste. Es un mecanismo de consenso, no de integridad: solo hace falta cuando nadie manda.', v: 'prueba de trabajo proof of work mineria dificultad nonce ceros consenso', i: 'cr-cadena' },
{ t: 'Ataque por canal lateral', d: 'El que no ataca la matemática sino lo que su ejecución deja escapar: el tiempo que tarda, el consumo eléctrico, los mensajes de error que devuelve. Es la diferencia entre el algoritmo y el sistema, y la razón principal de que no se implemente criptografía a mano sino con bibliotecas revisadas.', v: 'canal lateral side channel tiempo consumo fugas implementacion', i: 'cr-canales' },
{ t: 'Tiempo constante', d: 'La manera de operar con secretos para que la duración no dependa de ellos: al comparar dos etiquetas se recorren siempre todos los bytes acumulando diferencias, sin salir en el primero que falla. Una comparación normal tarda distinto según cuántos bytes se acierten, y ese tiempo permite averiguar la etiqueta byte a byte.', v: 'tiempo constante comparacion segura fuga de tiempo timing', i: 'cr-canales' },
{ t: 'Oráculo de relleno', d: 'El ataque que aprovecha que un servidor distinga «el relleno está mal» de «la autenticación está mal»: esa única diferencia, repetida byte a byte, descifra el mensaje entero sin llegar a conocer la clave. Se evita autenticando antes de descifrar y devolviendo siempre el mismo error.', v: 'oraculo de relleno padding oracle cbc error relleno vaudenay', i: 'cr-canales' },
{ t: 'Cifrado homomórfico', d: 'Aquel en el que operar sobre los textos cifrados equivale a operar sobre los mensajes sin llegar a abrirlos. RSA lo es sin querer para el producto, y Paillier para la suma: $E(m_1)E(m_2) = E(m_1 + m_2)$, lo que permite contar votos sin abrir ningún sobre. El totalmente homomórfico, desde Gentry en 2009, suma y multiplica sin límite, aunque todavía despacio.', v: 'homomorfico paillier gentry votar cifrado recuento calcular sobre cifrados', i: 'cr-homomorfico' },
{ t: 'Algoritmo de Shor', d: 'El algoritmo cuántico que factoriza en tiempo polinómico. Factorizar $n$ se reduce a encontrar el orden de un número módulo $n$, y lo único que un ordenador normal no sabe hacer deprisa es encontrar ese periodo; el cuántico lo saca con una transformada de Fourier. Rompe RSA, Diffie-Hellman y las curvas elípticas, es decir, toda la clave pública de hoy.', v: 'shor cuantico factorizar periodo orden fourier romper rsa', i: 'cr-cuantico' },
{ t: 'Algoritmo de Grover', d: 'El algoritmo cuántico que busca entre $N$ posibilidades en unos $\\sqrt N$ pasos. Contra los cifrados simétricos y las funciones hash solo saca la raíz cuadrada, así que AES-128 se quedaría en 64 bits de seguridad y basta con doblar el tamaño: AES-256 y SHA-256 aguantan. Es la diferencia con Shor, que no deja nada en pie.', v: 'grover cuantico busqueda raiz cuadrada aes 256 simetrico', i: 'cr-cuantico' },
{ t: 'Criptografía poscuántica', d: 'La que corre en un ordenador normal y resiste a uno cuántico. Las dos familias que se están normalizando son los retículos y las firmas construidas solo con funciones hash. Se paga en tamaño, y la transición ya está en marcha de forma híbrida —clásico más poscuántico— porque quien grabe hoy tráfico cifrado podrá descifrarlo el día que exista la máquina.', v: 'poscuantica postcuantica reticulos kyber dilithium cosechar ahora descifrar despues hibrido', i: 'cr-poscuantico' },
{ t: 'Aprendizaje con errores (LWE)', d: 'El problema de resolver un sistema de ecuaciones lineales al que se le ha sumado un error pequeño en cada ecuación. Sin el error lo despeja Gauss en un momento; con él no se conoce manera de hacerlo, ni siquiera con un ordenador cuántico. Sobre esa dificultad se construye la criptografía de retículos, que es la principal apuesta poscuántica.', v: 'lwe aprendizaje con errores reticulos error ruido gauss', i: 'cr-poscuantico' },
{ t: 'Firma de Lamport', d: 'Una firma hecha solo con una función hash: para cada bit del mensaje se publican los hashes de dos secretos, y firmar consiste en revelar uno de los dos según el bit valga 0 o 1. Su seguridad no depende de ningún problema de teoría de números, solo del hash, y a cambio cada clave sirve para firmar una sola vez.', v: 'lamport firma con hash un solo uso poscuantica secretos', i: 'cr-poscuantico' },
{ t: 'BB84', d: 'El protocolo que reparte una clave enviando fotones polarizados en dos bases elegidas al azar. Medir en la base equivocada da un bit al azar y además altera el fotón, así que una espía introduce un 25 % de errores en la clave cribada. Lo que garantiza no es que nadie escuche, sino que escuchar se nota, y entonces esa clave se tira.', v: 'bb84 cuantica distribucion de claves fotones bases cribar bennett brassard', i: 'cr-bb84' },
{ t: 'Trinquete', d: 'El mecanismo de la mensajería cifrada que deriva una clave nueva para cada mensaje pasando la anterior por una función hash. Como el hash no se invierte, quien capture el estado de hoy no puede leer lo de ayer. El doble trinquete añade además un Diffie-Hellman nuevo en cada respuesta, con lo que también recupera el futuro si el estado llegó a filtrarse.', v: 'trinquete ratchet doble trinquete signal mensajeria clave por mensaje', i: 'cr-bolsillo' },
/* ---------------- máquinas y lenguajes ---------------- */
{ t: 'Quine', d: 'Un programa que escribe su propio texto y nada más. No funciona guardando una copia -eso siempre sería más grande que el programa-, sino guardando el texto <strong>una vez y usándolo dos</strong>: como dato que se escribe y como instrucciones que se ejecutan, igual que una célula con su ADN. El teorema de recursión de Kleene garantiza que existe en cualquier lenguaje suficientemente potente. El nombre se lo puso Hofstadter por el filósofo Willard van Orman Quine.', v: 'quine autorreferencia se escribe a si mismo kleene recursion', i: 'len-autorreferencia' },
{ t: 'Bootstrapping', d: 'Construir un compilador escribiéndolo primero en otro lenguaje, reescribiéndolo después en el lenguaje que compila y compilándolo con el viejo: a partir de ahí se compila a sí mismo. Es como están hechos casi todos los compiladores en uso, y tiene una consecuencia que descubrió Ken Thompson en 1984: una trampa metida en un compilador puede reproducirse en todo lo que compile -incluidos los compiladores- y <strong>no aparecer en ningún código fuente</strong>. La respuesta práctica es la compilación reproducible.', v: 'bootstrapping compilador se compila thompson trusting trust reproducible', i: 'len-autorreferencia' },
{ t: 'Plegar constantes', d: 'La optimización más sencilla que hace un compilador: si un nudo del árbol tiene sus dos ramas ya resueltas en números, el resultado se calcula <strong>al compilar</strong> y se deja el número puesto. Se hace de abajo arriba, y al plegar uno el de encima puede quedarse plegable también. Va de la mano de quitar <em>código muerto</em>: si la condición de un «si» se pliega, la rama que no se ejecuta desaparece. Optimizar es cambiar un programa por otro que hace <strong>exactamente lo mismo</strong> y cuesta menos. Si cambia lo que hace, no es una optimización: es un fallo, y la única forma de saberlo es correr las dos versiones y comparar. Las dos más sencillas son <em>plegar constantes</em> -calcular al compilar lo que ya se sabe- y quitar <em>código muerto</em> -tirar la rama de un «si» cuya condición ya está decidida-. Casi todas llevan una condición escondida, y comprobarla es la mayor parte del trabajo.', v: 'plegar constantes optimizar codigo muerto compilador mejorar', i: 'len-optimizar' },
{ t: 'Compilador', d: 'Un programa que recorre el árbol de otro programa <strong>escribiendo instrucciones</strong> en vez de ejecutándolas. Es el mismo recorrido que hace un intérprete, con otra acción al pasar por cada nudo. Su ventaja no es solo la velocidad: analiza una sola vez y caza los fallos de nombres antes de ejecutar nada. Un compilador equivocado genera código que se lee perfectamente, así que la única prueba es correr el programa por los dos caminos y comparar lo que escriben.', v: 'compilador interprete traducir generar codigo prueba diferencial', i: 'len-compilar' },
{ t: 'Marco de llamada', d: 'Lo que una función necesita para existir mientras corre: sus parámetros, sus variables locales y la dirección a la que hay que volver. Nace al llamarla y muere al terminar. En una recursión hay <strong>varios marcos vivos a la vez</strong>, cada uno con su propio valor del parámetro, y por eso la pila crece con la profundidad de la recursión y no con el tamaño del resultado. Cuando no hay caso base -o la llamada no se acerca a él- la pila se llena: eso es el desbordamiento de pila.', v: 'marco de llamada frame pila recursion desbordamiento caso base', i: 'len-funciones' },
{ t: 'Entorno', d: 'Lo que un intérprete consulta al encontrarse un nombre: una <strong>aplicación</strong> de un conjunto de nombres en el conjunto de los valores. Declarar es añadir un par, asignar es cambiar una imagen y usar el nombre es evaluarla. Cada llamada crea un entorno nuevo que apunta al de fuera, y buscar un nombre es mirar dentro y subir si no está: eso es el <strong>ámbito</strong>, y por eso la variable de dentro tapa a la de fuera sin pisarla.', v: 'entorno ambito scope variables aplicacion nombres valores tapar', i: 'len-variables' },
{ t: 'Notación polaca inversa', d: 'Escribir las operaciones detrás de sus operandos: <code>2 3 4 * +</code>. Sale de recorrer el árbol de una expresión visitando las ramas antes que el nudo -recorrido en <strong>postorden</strong>- y no necesita paréntesis ni reglas de prioridad, porque el orden ya lo dice todo. Se evalúa con una pila: los números se meten y cada operación saca dos y mete el resultado. La inventó el lógico Jan Łukasiewicz hacia 1924 para escribir fórmulas sin paréntesis, sin ninguna máquina a la vista.', v: 'polaca inversa rpn postorden pila lukasiewicz sin parentesis', i: 'len-pila' },
{ t: 'Descenso recursivo', d: 'La forma de construir un analizador escribiendo <strong>una función por regla</strong> de la gramática, cada una llamando a la de la capa de abajo. Es casi una transcripción de la gramática, y tiene una consecuencia elegante: la <strong>prioridad</strong> de las operaciones sale del orden en que las funciones se llaman, y la <strong>asociatividad</strong>, de dónde se cuelga lo acumulado dentro del bucle. No hay ninguna tabla de prioridades en ninguna parte.', v: 'descenso recursivo analizador parser precedencia asociatividad', i: 'len-arbol' },
{ t: 'Gramática', d: 'Un puñado de reglas que dicen cómo se construye una frase válida a partir de piezas. Una regla puede nombrarse a sí misma, y por eso unas pocas generan infinitos programas. Es <strong>ambigua</strong> si alguna frase se puede construir de dos maneras, y entonces no vale para un lenguaje de programación: <code>2 + 3 * 4</code> podría valer 14 o 20. La cura es escribir las expresiones en capas, una por nivel de prioridad. Notación de Backus y Naur, 1959, sobre la clasificación de Chomsky de 1956.', v: 'gramatica bnf backus naur chomsky ambigua reglas derivar', i: 'len-gramatica' },
{ t: 'Analizador léxico', d: 'Lo primero que hace un traductor: partir el texto en piezas con nombre -número, nombre, palabra del lenguaje o símbolo-, que se llaman <em>tokens</em>. Cuidado con la palabra: los tokens de un modelo de lenguaje son otra cosa. A partir del troceo, el texto original ya no se vuelve a mirar. Los espacios, los saltos de línea y los comentarios <strong>desaparecen</strong>: son separadores, no piezas. Por dentro el troceador es un autómata, y su única sutileza es que el carácter que cierra una pieza es el primero de la siguiente, así que hay que mirarlo sin quedárselo.', v: 'analizador lexico token trocear automata piezas lexer', i: 'len-tokens' },
{ t: 'Pizca', d: 'El lenguaje de programación que se construye en la segunda mitad del bloque de máquinas y lenguajes. Siete palabras -<code>sea</code>, <code>si</code>, <code>sino</code>, <code>mientras</code>, <code>fun</code>, <code>vuelve</code>, <code>muestra</code>-, cuatro operaciones y seis comparaciones. Corre de dos maneras: interpretado recorriendo su árbol, y compilado a las instrucciones de la CPU del tramo A. Sus números son los de esa máquina, de -128 a 127 y con vuelta al desbordar, para que las dos maneras den siempre lo mismo.', v: 'pizca lenguaje curso siete palabras interprete compilador', i: 'len-tokens' },
{ t: 'Ensamblador', d: 'El traductor más sencillo que hay: una línea de texto, una instrucción de máquina. No inventa nada, solo pone nombres -a las instrucciones, a las celdas de datos y a los sitios a los que se salta-. Lee el programa <strong>dos veces</strong>, porque un salto hacia delante nombra una etiqueta que todavía no ha visto; en la primera pasada mide y apunta dónde cae cada etiqueta, y en la segunda rellena los huecos.', v: 'ensamblador assembler etiquetas dos pasadas mnemonico', i: 'maq-ensamblador' },
{ t: 'Salto condicional', d: 'La única forma de decidir que tiene una máquina: una instrucción que salta <strong>solo si</strong> el acumulador vale cero. De ahí salen todos los «si» y todos los «mientras» de cualquier lenguaje. Tiene una consecuencia que despista al escribirlo a mano: la condición se pone <strong>al revés</strong>, porque el salto se lleva el caso en que no se cumple.', v: 'salto condicional sicero bifurcacion si mientras bucle', i: 'maq-ensamblador' },
{ t: 'Pila', d: 'Una lista de la que solo se puede tocar el último elemento: lo último que entra es lo primero que sale. En la máquina sirve para dos cosas que en realidad son la misma -acordarse de lo que se estaba haciendo antes-: guardar resultados intermedios de una operación, y guardar la dirección a la que hay que volver cuando termine una subrutina. Por eso las llamadas anidadas se deshacen solas en el orden correcto.', v: 'pila stack lifo subrutina llamada direccion de vuelta', i: 'maq-ensamblador' },
{ t: 'Ciclo de instrucción', d: 'Los tres tiempos que un procesador repite sin parar: <strong>buscar</strong> la instrucción que marca el contador de programa, <strong>decodificarla</strong> y <strong>ejecutarla</strong>. Ninguna pieza es nueva: el contador es un registro con un sumador, decodificar son detectores de fila y elegir la operación es un multiplexor. Un procesador es todo lo anterior metido en un bucle, y «gigahercio» significa cuántas veces por segundo lo da.', v: 'ciclo instruccion buscar decodificar ejecutar fetch contador de programa', i: 'maq-cpu' },
{ t: 'Programa almacenado', d: 'La idea de que el programa vive en la misma memoria que los datos, como números indistinguibles de ellos: lo que hace que una celda sea una instrucción es que el contador pase por ahí, y nada más. De ahí salen el poder de la máquina -cambiar de programa es escribir números, no recablear- y sus peores fallos de seguridad, porque un contador perdido ejecuta lo que encuentre. Se fijó en el informe del EDVAC de 1945 y corrió por primera vez en el <em>Baby</em> de Mánchester en 1948.', v: 'programa almacenado von neumann edvac memoria unica datos instrucciones', i: 'maq-cpu' },
{ t: 'Decodificador', d: 'El circuito que convierte un número de $n$ bits en $2^n$ cables de los que siempre hay exactamente uno encendido. Es lo que hace que un 6 en la memoria active el circuito de sumar y ninguno de los otros, o sea, es todo lo que significa que una máquina «entienda» una instrucción. Por dentro no es más que todos los detectores de fila posibles puestos juntos.', v: 'decodificador decoder senales de control entender instruccion', i: 'maq-cpu' },
{ t: 'Suma de productos', d: 'La receta que convierte <strong>cualquier</strong> tabla de verdad en un circuito sin necesidad de ninguna idea feliz: por cada fila que valga 1 se pone un <code>and</code> con todas las entradas -negadas las que en esa fila valgan 0-, y todos esos detectores se juntan con un <code>or</code>. También se le llama forma normal disyuntiva, y de ella sale la respuesta a qué se puede construir con puertas: todo. Es correcta y es cara: al <code>xor</code>, que cuesta una puerta, le saca cinco.', v: 'suma de productos forma normal disyuntiva receta minterminos detector', i: 'maq-normal' },
{ t: 'Implicante primo', d: 'Un <code>and</code> de la suma de productos que ya no se puede agrandar más fundiéndolo con otro. Fundir es la regla $x\\,y + x\\,\\bar y = x$: si dos filas que valen 1 se diferencian en una sola entrada, esa entrada sobra y se tacha. Quedarse con los primos y elegir los que hagan falta es el método de Quine-McCluskey, y da un circuito barato aunque no necesariamente el mínimo: encontrar el mínimo de verdad es un problema duro.', v: 'implicante primo fundir agrupar quine mccluskey simplificar', i: 'maq-normal' },
{ t: 'Mapa de Karnaugh', d: 'La tabla de verdad colocada en cuadrícula con las columnas en el orden 0, 1, 3, 2 -escrito en binario: 00, 01, 11, 10- en vez del de contar. Con ese orden <strong>dos casillas vecinas se diferencian siempre en una sola variable</strong>, así que fundir se convierte en rodear casillas pegadas y se hace de un vistazo. Los bordes también son vecinos: la última columna toca la primera. Lo publicó Maurice Karnaugh en 1953 y sirve a mano hasta cuatro o cinco entradas.', v: 'karnaugh mapa cuadricula gray vecinas agrupar', i: 'maq-normal' },
{ t: 'Biestable', d: 'El circuito que recuerda un bit, hecho con dos puertas cruzadas en las que la salida de cada una entra en la otra. Se llama así porque con las mismas entradas admite <strong>dos estados que se sostienen solos</strong>, y cuál de los dos esté vigente depende de lo que ocurrió antes: por eso tiene historia y por eso es memoria. Lo publicaron Eccles y Jordan en 1919 buscando un contador, y en inglés se le dice <em>flip-flop</em>.', v: 'biestable cerrojo latch flip-flop memoria bucle recordar', i: 'maq-memoria' },
{ t: 'Metaestabilidad', d: 'El estado de indecisión en que puede quedar un biestable cuando nada rompe el empate entre sus dos puertas: ni se asienta en 0 ni en 1. En el simulador de este curso aparece como una <strong>oscilación</strong> que no acaba; en un circuito real la rompe por azar la puerta que sea un poco más rápida. No es teórica: cuando un dato cruza de una parte del sistema a otra con otro reloj, se encadenan dos o tres biestables para darle tiempo a decidirse.', v: 'metaestabilidad indecision oscila empate relojes distintos', i: 'maq-memoria' },
{ t: 'Reloj', d: 'La señal común que marca el compás de un circuito. Se añade una puerta de permiso que solo deja entrar las órdenes mientras el reloj vale 1, de modo que los cambios ocurren en <strong>momentos conocidos</strong> y no en cuanto llega cada cable. No hace el circuito más rápido -lo hace más lento, a propósito-: lo que consigue es que las partes que van a distinta velocidad no se lean unas a otras a medio camino.', v: 'reloj clock compas sincronizar permiso flanco', i: 'maq-memoria' },
{ t: 'Registro', d: 'Una fila de biestables con el mismo reloj, que guarda una palabra entera en vez de un bit: ocho de ellos son un byte. Es donde un procesador tiene lo que está usando <em>ahora mismo</em>, y es la memoria más rápida que hay porque está hecha de puertas. La memoria principal usa en cambio condensadores diminutos, más baratos y más lentos, y esa diferencia de tecnología es la razón de que un ordenador tenga poca memoria rápida y mucha lenta.', v: 'registro palabra byte procesador cache memoria rapida', i: 'maq-memoria' },
{ t: 'Multiplexor', d: 'El circuito que elige entre dos entradas según un cable de control: con el control a 0 deja pasar una y con el control a 1 la otra. Es la forma en que un circuito «decide», y tiene una consecuencia que sorprende: <strong>las dos ramas se calculan siempre</strong> y la no elegida se tira, porque las puertas están todas encendidas y no hay nada que saltarse. Es la misma idea que evitar el <code>if</code> en un shader con <code>mix</code>.', v: 'multiplexor mux elegir seleccionar mix control', i: 'maq-decidir' },
{ t: 'Acarreo', d: 'Lo que una columna se lleva a la siguiente al sumar. En binario aparece en cuanto hay dos unos, porque $1+1$ es «cero y me llevo una». Una columna <strong>genera</strong> acarreo si sus dos bits valen 1 -y entonces no espera a nadie- y lo <strong>propaga</strong> si uno vale 1 y el otro 0, dejando pasar el que le llegue; propagar es lo que obliga a esperar y lo que hace lento a un sumador encadenado.', v: 'acarreo carry llevarse una generar propagar', i: 'maq-sumador' },
{ t: 'Sumador completo', d: 'El circuito que suma tres bits -los dos que le tocan y el acarreo que le llega de la columna anterior- y devuelve la suma y el acarreo de salida. Cuesta cinco puertas y es la pieza que se repite una vez por columna. El <em>semi</em>sumador, de sólo dos puertas, no sirve más que para la columna de la derecha, porque no sabe recibir acarreo.', v: 'sumador completo semisumador full adder columna', i: 'maq-sumador' },
{ t: 'Puerta lógica', d: 'Un trozo de circuito con unas entradas y una salida, definido enteramente por qué saca en cada combinación de entradas: es decir, por una tabla de verdad. La conectiva de la lógica y la puerta del circuito no se parecen, <strong>son el mismo objeto</strong>, una escrita con símbolos y otra con cables.', v: 'puerta logica gate and or not circuito', i: 'maq-puertas' },
{ t: 'NAND', d: 'La puerta «no y»: saca 0 sólo cuando todas sus entradas valen 1. Su interés es que basta ella sola para construir todas las demás -<code>nand(a, a)</code> niega, y de ahí salen el and y el or-, propiedad que se llama ser <strong>funcionalmente completa</strong> y que comparte con la nor. Por eso los chips se fabrican repitiendo una única pieza. La demostró Henry Sheffer en 1913, décadas antes de que hubiera dónde enchufarla.', v: 'nand no y sheffer funcionalmente completa barra', i: 'maq-puertas' },
{ t: 'Netlist', d: 'La descripción de un circuito en texto, una puerta por línea, con el nombre del cable que sale a la izquierda del igual: <code>s = xor(a, b);</code>. En este curso los circuitos se escriben así y el diagrama se genera solo, porque el texto es accesible con teclado y se corrige comparando la tabla de verdad, de modo que vale cualquier circuito equivalente.', v: 'netlist circuito texto cables puertas', i: 'maq-puertas' },
{ t: 'Bit', d: 'La distinción entre dos estados, que es lo único que una máquina sabe hacer. En un circuito es un cable con tensión o sin ella; en teoría de la información es cuánto se aprende al resolver una duda entre dos opciones igual de probables. Las dos cosas son el mismo concepto visto desde dos sitios: la palabra la propuso John Tukey como contracción de <em>binary digit</em>.', v: 'bit binario dos estados cable tension', i: 'maq-bits' },
{ t: 'Byte', d: 'Un grupo de ocho bits, que por tanto admite $2^8 = 256$ valores distintos. Es la unidad en la que se mide la memoria y la que explica los límites redondos que aparecen por todas partes: los números del 0 al 255 de una dirección IP, los 256 tonos de cada color de una pantalla o el tope de 255 caracteres de tantos formularios.', v: 'byte octeto ocho bits 256', i: 'maq-bits' },
{ t: 'Hexadecimal', d: 'La escritura en base 16, con los símbolos 0-9 y A-F. No es otro sistema de numeración: como $16 = 2^4$, <strong>cada cuatro bits son exactamente un símbolo</strong>, de modo que sirve para acortar cadenas de bits sin hacer ninguna cuenta. Se marca con el prefijo <code>0x</code>: <code>0x1F</code> vale $1\\cdot16 + 15 = 31$.', v: 'hexadecimal hex base 16 0x', i: 'maq-bits' },
{ t: 'Complemento a dos', d: 'La forma de escribir los números negativos en una máquina: $-n$ se guarda como $2^k - n$, y a mano se obtiene invirtiendo cada bit y sumando uno. Se eligió sobre otras porque <strong>hace que la suma de siempre siga valiendo</strong> -con ella $5 + (-5)$ da cero usando el mismo circuito- y por tanto restar no necesita un circuito propio. Que el primer bit valga 1 en todos los negativos no es una regla aparte: sale solo.', v: 'complemento a dos negativos signo dos c2', i: 'maq-bits' },
{ t: 'Desbordamiento', d: 'Lo que ocurre cuando el resultado de una cuenta no cabe en los bits disponibles: los que sobran se caen, sin ningún aviso. Con signo tiene una forma llamativa, porque el rango da la vuelta y sumar uno al mayor positivo devuelve el menor negativo. Destruyó el primer vuelo del cohete Ariane 5 en 1996, al pasar una velocidad de 64 bits a un entero de 16.', v: 'desbordamiento overflow rango se sale ariane', i: 'maq-bits' },
];